window.__REGISTER_BANK__({"id":"zhenti304","name":"国省考判断真题","shortName":"判断真题","subtitle":"小P公考2027版 · 2021–2026国考真题完整6套（230题 · 含高清图推 & 一拖五）","icon":"🎯","chapterPrefix":"套","chapterNames":{"1":"2021年国考副省级卷","2":"2022年国考地市级卷","3":"2023年国考地市级卷","4":"2024年国考地市级卷","5":"2025年国考副省级卷","6":"2026年国考副省级卷"},"questions":[{"id":1,"chapter":1,"num":1,"source":"2021国考副省级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"A","page":4,"stemImages":["banks/zhenti304_imgs/p004_f01.webp"]},{"id":2,"chapter":1,"num":2,"source":"2021国考副省级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"C","page":4,"stemImages":["banks/zhenti304_imgs/p004_f02.webp"]},{"id":3,"chapter":1,"num":3,"source":"2021国考副省级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"A","page":4,"stemImages":["banks/zhenti304_imgs/p004_f03.webp"]},{"id":4,"chapter":1,"num":4,"source":"2021国考副省级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"D","page":4,"stemImages":["banks/zhenti304_imgs/p005_f01.webp"]},{"id":5,"chapter":1,"num":5,"source":"2021国考副省级","type":"图形推理","stem":"左图给定的是正方体纸盒，右边哪项可能是其正确的外表面展开图？","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"A","page":5,"stemImages":["banks/zhenti304_imgs/p005_f02.webp"]},{"id":6,"chapter":1,"num":6,"source":"2021国考副省级","type":"图形推理","stem":"左图给定的是由18个相同大小的正方体组合成的多面体，这个多面体可以切割为3个完全相同的小多面体，问切成的小多面体是：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"A","page":5,"stemImages":["banks/zhenti304_imgs/p005_f03.webp"]},{"id":7,"chapter":1,"num":7,"source":"2021国考副省级","type":"图形推理","stem":"左图为给定的多面体，从任一角度观看，下面哪项可能是该多面体的视图？","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":5,"stemImages":["banks/zhenti304_imgs/p005_f04.webp"]},{"id":8,"chapter":1,"num":8,"source":"2021国考副省级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①②③，④⑤⑥","B":"①②④，③⑤⑥","C":"①③④，②⑤⑥","D":"①③⑤，②④⑥"},"answer":"C","page":5,"stemImages":["banks/zhenti304_imgs/p005_f05.webp"]},{"id":9,"chapter":1,"num":9,"source":"2021国考副省级","type":"图形推理","stem":"把下面的六个图形分为两类,使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①②④，③⑤⑥","B":"①③⑤，②④⑥","C":"①③⑥，②④⑤","D":"①⑤⑥，②③④"},"answer":"D","page":6,"stemImages":["banks/zhenti304_imgs/p006_f01.webp"]},{"id":10,"chapter":1,"num":10,"source":"2021国考副省级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①③④，②⑤⑥","B":"①③⑤，②④⑥","C":"①②⑥，③④⑤","D":"①④⑥，②③⑤"},"answer":"C","page":6,"stemImages":["banks/zhenti304_imgs/p006_f02.webp"]},{"id":11,"chapter":1,"num":11,"source":"2021国考副省级","type":"定义判断","stem":"串对是指在诗句或对联中，出句与对句在意义上和语法结构上不是相对，而是上下相承，两句不能互相脱离,更不能颠倒,在语言结构上有一定的前后顺序。","prompt":"根据上述定义，下列属于串对的是：","options":{"A":"到此已穷千里目，谁知才上一层楼","B":"书山有路勤为径，学海无涯苦作舟","C":"横眉冷对千夫指，俯首甘为孺子牛","D":"江间波浪兼天涌，塞上风云接地阴"},"answer":"A","page":6},{"id":12,"chapter":1,"num":12,"source":"2021国考副省级","type":"定义判断","stem":"互益素是一种生物释放的、能引起他种接受生物产生对释放者和接受者都有益的反应的信息化学物质。","prompt":"根据上述定义,下列涉及互益素的是：","options":{"A":"苹果实蝇在植物果实上产卵后会留下一种标记信息素，以避免自己再次到这里产卵","B":"楝科植物印楝的种子、树叶和树皮中含有的印楝素，对几乎所有害虫都有驱杀效果","C":"亚洲玉米雌蛾释放的性信息素能够吸引雄蛾，使雄蛾能够准确找到雌蛾的方位","D":"小麦在遭受麦长管蚜攻击后会释放出水杨酸甲酯,可吸引麦长管蚜的天敌异色瓢虫"},"answer":"D","page":6},{"id":13,"chapter":1,"num":13,"source":"2021国考副省级","type":"定义判断","stem":"国际多式联运是指按照多式联运合同，以至少两种不同的运输方式，由多式联运经营人将货物从一国境内接货地点运至另一国境内指定交货地点的一种运输方式。","prompt":"根据上述定义,下列属于国际多式联运的是：","options":{"A":"将货运汽车直接开上火车车皮进行铁路运输，到达目的地再把货车从车皮上开下来","B":"某公司为员工采购进口商品，通过厢式货车运送到公司楼下，员工再开车将商品带回家","C":"电商从海外采购生鲜商品，由物流公司通过航空冷链进口到国内，然后由冷链车运至全国各地","D":"船运公司将从外海打捞的海鲜运输到沿海地区,再由买家分销到各个生鲜市场"},"answer":"C","page":7},{"id":14,"chapter":1,"num":14,"source":"2021国考副省级","type":"定义判断","stem":"统计数据分为定性数据与定量数据。定性数据包括分类数据和顺序数据。分类数据是指只能归于某一类别的非数字型数据，它是对事物进行分类的结果，用文字表述;顺序数据是指归于某一有序类别的非数字型数据。定量数据是指表现为具体数字观测值的数据。\n①按城市规模可将城市分为特大城市、大城市、中等城市和小城市;\n②婚姻状况：1-未婚，2-已婚，3-离异，4-丧偶;\n③A 地到B 地的距离为 200 公里，到C地为320公里，到 D地为100公里;\n④某医院建筑面积37.5万平方米，开放床位3182个,临床医生 687 个。","prompt":"根据上述定义，关于以上 4组数据的说法正确的是:","options":{"A":"②④都是分类数据","B":"②③④都是定量数据","C":"①②都是顺序数据","D":"仅②是分类数据"},"answer":"D","page":7},{"id":15,"chapter":1,"num":15,"source":"2021国考副省级","type":"定义判断","stem":"拮抗作用是一种常见的感觉变化现象，是指因一种呈味物质的存在，而使另一种呈味物质的呈味特性减弱的现象。","prompt":"根据上述定义，下列没有体现拮抗作用的是：","options":{"A":"在橘子汁中添加少量柠檬酸会感觉甜味减弱，如再加砂糖，又会感到酸味减弱","B":"糖精带有苦味,在糖精中添加少量的谷氨酸钠，苦味可明显缓和","C":"同时服用氯化钠和奎宁后，再饮用清水会有微甜的感觉","D":"在食用过酸涩的西非山榄后，再吃酸味食品,会尝不到酸味"},"answer":"C","page":7},{"id":16,"chapter":1,"num":16,"source":"2021国考副省级","type":"定义判断","stem":"通过提供产品及服务使顾客产生愉悦等积极情感，从而使顾客觉得从产品及服务中获得了超过使用价值的新价值，以此为手段进行情感营销的过程，称为情感价值链。","prompt":"根据上述定义，下列没有凸显情感价值链的是：","options":{"A":"小张从事美容工作多年，她总是专注而耐心地倾听客户说话，让客户在享受按摩的同时心情舒畅","B":"智能音箱“小美\"深受孩子们喜爱，因为它不仅能播放儿歌和故事，还能跟小朋友“对话、握手和点头”","C":"电视上，一对年轻夫妻为“该谁扫地了\"而犯愁，之后扫地机器人登场，并闪现广告语“有了它，更幸福”","D":"洗碗机广告中，一位女士愁眉苦脸刷着油腻的碗盘，看着自己粗糙的双手，广告词是“你要做这样的女人吗？”"},"answer":"B","page":7},{"id":17,"chapter":1,"num":17,"source":"2021国考副省级","type":"定义判断","stem":"预测干预是指人们受预测信息的影响而采取了某种行为，造成原本有多种可能性的结果真的朝着预测所指示的方向发展。","prompt":"根据上述定义,下列属于预测干预的是：","options":{"A":"某次财经访谈栏目中一名专家预测H股票将大涨，结果很多收看该节目的观众争相购买该股票，导致该股票涨停","B":"某福利彩票代销点宣称他们卖出的彩票多次中奖,结果到该代销点购买彩票的人经常排起长队","C":"某国首脑在新年致辞中对该国经济形势进行了展望，因而该国老百姓对未来经济好转充满了信心","D":"甲国大选前，与其敌对的乙国媒体大肆渲染，认为M 党总统候选人将当选，结果甲国很多选民转而支持N 党总统候选人"},"answer":"A","page":8},{"id":18,"chapter":1,"num":18,"source":"2021国考副省级","type":"定义判断","stem":"人们常常系统地高估自己对事件的控制程度或影响力，而低估机会、运气等不可控制因素在事件发展过程及其结果上所扮演的角色，这一现象被称为控制错觉。","prompt":"根据上述定义,下列没有体现控制错觉的是：","options":{"A":"人们想用骰子掷出“双 6\"时会在心中默念，用力揉捏骰子，相信这样做就会如愿","B":"一些股民往往借助几个简单的因素预测大盘指数,结果常常是谬以千里","C":"某企业经理认为今年当地举办的运动会对企业发展非常有利,预测今年营业额会有所上涨","D":"景区某摆渡车驾驶员常年走山路,认为自己路况熟、技术好，所以在山路上开得非常快"},"answer":"C","page":8},{"id":19,"chapter":1,"num":19,"source":"2021国考副省级","type":"定义判断","stem":"对立互补命题指的是先后叙述的两个结构基本相同的句式中含有两对或者两对以上相互对立的概念，但是其阐发的意思是一致的或者是相互补充的。","prompt":"根据上述定义,下列不属于对立互补命题的是:","options":{"A":"君子坦荡荡，小人长戚戚","B":"先天下之忧而忧，后天下之乐而乐","C":"仓实而知礼节，衣食足而知荣辱","D":"穷在闹市无人问，富在深山有远亲"},"answer":"C","page":8},{"id":20,"chapter":1,"num":20,"source":"2021国考副省级","type":"定义判断","stem":"一般来说，科学实验中主要涉及三种变量：自变量、因变量和控制变量。自变量是指在实验中由实验者操作的变量。因变量是指随着自变量的变化而变化的变量。控制变量是指实验中除自变量以外的影响实验变化和结果的潜在因素或条件。","prompt":"根据上述定义,下列说法正确的是：","options":{"A":"研究小麦供给量受当地采购价格的影响，小麦供给量是控制变量，采购价格是因变量","B":"研究不同税率对稀土出口量的影响，稀土出口量是自变量，税率是因变量","C":"研究气候条件对棉花产量的影响，气候条件是因变量,害虫影响是控制变量","D":"研究制糖厂营业额受糖产量的影响，糖的单价是控制变量,糖产量是自变量"},"answer":"D","page":8},{"id":21,"chapter":1,"num":21,"source":"2021国考副省级","type":"类比推理","stem":"江河湖海：水体","prompt":"","options":{"A":"寡孤独：身份","B":"油盐酱醋：调味","C":"山珍海味：美食","D":"绫罗绸缎：面料"},"answer":"D","page":9},{"id":22,"chapter":1,"num":22,"source":"2021国考副省级","type":"类比推理","stem":"船舶抛锚：请求救援","prompt":"","options":{"A":"安全着陆：平稳飞行","B":"行政复议：获得赔偿","C":"卖出高梁：买入白酒","D":"违规销售：停业整顿"},"answer":"D","page":9},{"id":23,"chapter":1,"num":23,"source":"2021国考副省级","type":"类比推理","stem":"春山暖日和风：阑干楼阁帘拢","prompt":"","options":{"A":"绿蚁新酒：红泥小火炉","B":"鸡声茅店月：人迹板桥霜","C":"江碧鸟逾白：山青花欲燃","D":"柴门闻犬吠：风雪夜归人"},"answer":"B","page":9},{"id":24,"chapter":1,"num":24,"source":"2021国考副省级","type":"类比推理","stem":"立体化战争：数字化战争","prompt":"","options":{"A":"民主型管理：专制型管理","B":"防风林：观赏树木","C":"有氧运动：医疗瘦身","D":"绩效奖励：物质奖励"},"answer":"D","page":9},{"id":25,"chapter":1,"num":25,"source":"2021国考副省级","type":"类比推理","stem":"风筝：蔑刀：竹条","prompt":"","options":{"A":"泥塑：黏土：颜料","B":"绣品：绣针：绣线","C":"糖人：蔗糖：竹签","D":"漆器：描金：涂料"},"answer":"B","page":9},{"id":26,"chapter":1,"num":26,"source":"2021国考副省级","type":"类比推理","stem":"檀香：麝香：香料","prompt":"","options":{"A":"木材：钢筋：建材","B":"日光：月光：光明","C":"薯条：粉条：食物","D":"鲸鱼：鲍鱼：海鱼"},"answer":"A","page":9},{"id":27,"chapter":1,"num":27,"source":"2021国考副省级","type":"类比推理","stem":"中央预算：年度预算：地方预算","prompt":"","options":{"A":"历史题材：军事题材：现实题材","B":"户外广告：文字广告：电视广告","C":"知识创新：技术创新：管理创新","D":"人身权利：生命权利：财产权利"},"answer":"A","page":9},{"id":28,"chapter":1,"num":28,"source":"2021国考副省级","type":"类比推理","stem":"健康监测：体检：疾病筛查","prompt":"","options":{"A":"为国聚财：税收：调节分配","B":"发掘遗迹：考古：考证年代","C":"解决争议：审判：强制执行","D":"太空飞行：航天：地质分析"},"answer":"A","page":10},{"id":29,"chapter":1,"num":29,"source":"2021国考副省级","type":"类比推理","stem":"(）对于 口罩相当于 竹子对于()","prompt":"","options":{"A":"耳挂;竹炭","B":"无纺布;斗笠","C":"卫生用品;竹叶","D":"医用口罩;箭竹"},"answer":"B","page":10},{"id":30,"chapter":1,"num":30,"source":"2021国考副省级","type":"类比推理","stem":"核安全对于（）相当于（）对于 虚拟货币","prompt":"","options":{"A":"核技术;货币","B":"核泄漏;交易货币","C":"国家安全;比特币","D":"网络安全;游戏币"},"answer":"C","page":10},{"id":31,"chapter":1,"num":31,"source":"2021国考副省级","type":"逻辑判断","stem":"中国互联网络信息中心发布报告显示,截至 2018年12月,我国短视频用户规模达6.48亿，其中青少年用户占了很大比重，开展青少年防沉迷工作刻不容缓。相关主管部门组织短视频平台企业研发了青少年防沉迷系统，进入“青少年模式\"后，每日使用时长将限定为累计40分钟,打赏、充值、提现、直播等功能将不可用，每天 22 时至次日6 时期间，禁止使用短视频App。","prompt":"以下哪项如果为真,最能质疑该模式的有效性？","options":{"A":"用户使用“青少年模式\"需提交身份证信息等，增加了泄露个人隐私的风险","B":"不加选择地浏览视频内容，可能会对青少年价值观产生负面影响","C":"该系统通过大数据分析来识别疑似青少年用户，可能会“误伤”成年人","D":"\"青少年模式\"目前尚无法识别网络使用者的真实身份"},"answer":"D","page":10},{"id":32,"chapter":1,"num":32,"source":"2021国考副省级","type":"逻辑判断","stem":"有研究人员认为，胶原蛋白保持皮肤年轻的说法并不科学，他们认为，皮肤得以保持年轻应归功于皮表干细胞。哺乳动物的皮表细胞会持续更新,细胞来源于表皮干细胞。这些干细胞会通过一种特定分化的多元蛋白结构—半桥粒附着在基膜上。表皮干细胞会不断复制分化，产生新细胞,取代受损的老细胞,这一更新有利于维持皮肤的年轻,因此表皮干细胞的更新才是保持皮肤年轻的原因。","prompt":"以下哪项如果为真,最能削弱上述结论?","options":{"A":"表皮干细胞的更新还需要其他化合物的促进","B":"表皮干细胞的再生能力会随着年龄的增长而衰退","C":"胶原蛋白对促进表皮干细胞的更新至关重要","D":"胶原蛋白的表达在不同干细胞之间存在很大差异"},"answer":"C","page":10},{"id":33,"chapter":1,"num":33,"source":"2021国考副省级","type":"逻辑判断","stem":"小赵和小刘是非常熟悉的好朋友，两家相距很近，疫情期间，小赵曾给本单位同处室的同事发了警示微信，小刘也给所在小区他认识的所有人发了警示微信，并进一步通过电话进行了确认提醒，小赵、小刘互通了电话，提醒近期不相互走动，小赵给小刘发过警示微信，小刘没有给小赵发过警示微信。","prompt":"根据以上陈述,以下哪项不可能？","options":{"A":"小赵近期没有去过小刘家","B":"小刘、小赵是同事","C":"小刘、小赵不是一个处室的","D":"小赵、小刘住一个小区"},"answer":"D","page":11},{"id":34,"chapter":1,"num":34,"source":"2021国考副省级","type":"逻辑判断","stem":"羟苯甲酮是一种常见的紫外线吸收剂,多用于防晒护肤品中，全球3500种品牌的防晒霜中均含有该物质，研究表明，即使是极低浓度的羟苯甲酮，也会给珊瑚带来致命的伤害，有专家指出，为了保护珊瑚，在海滨浴场应该禁止使用防晒霜。","prompt":"以下哪项如果为真，最能支持上述观点？","options":{"A":"一些远离海岸的大洋中部分水域已检测到羟苯甲酮，但浓度较低","B":"羟苯甲酮易引起皮肤过敏，长期使用会影响人体免疫力和生殖能力","C":"羟苯甲酮会破坏、改变珊瑚的 DNA,降低幼年珊瑚正常发育的几率","D":"人们在很多场合都使用防晒霜，仅在海滨浴场限制使用效果有限"},"answer":"C","page":11},{"id":35,"chapter":1,"num":35,"source":"2021国考副省级","type":"逻辑判断","stem":"某便利店新进了一批个性商品，如带酸味的啤酒，芥末味道的饼干等，这些个性商品摆放在单独设立的区域进行销售，三个月之后，店长发现：和之前没有引进个性商品时相比，店里的总销售额大幅提升，所以店长认为销售额增加的主要原因是引进了这些个性商品。","prompt":"以下哪项如果为真，最能支持店长的观点？","options":{"A":"三个月以来，这些个性化商品的销量和销售额都很有限","B":"来店消费的主要是年轻人，年轻人喜欢尝试新鲜事物","C":"近三个月，该店对货品摆放进行了重新规划和调整，货品陈列更加有序醒目","D":"除了增加个性商品，店里常规商品也增加了一些品牌和种类"},"answer":"B","page":11},{"id":36,"chapter":1,"num":36,"source":"2021国考副省级","type":"逻辑判断","stem":"研究人员在 2011年至 2017年间采集了600 多名 60 岁以上老年人的身高、血压和饮食习惯等多项数据，随后，又对研究对象进行了神经心理评估和认知障碍评定，在排除吸烟饮酒等风险因素后发现，那些每周吃两次、每次吃约150 克蘑菇的老年人，比每周吃蘑菇少于一次的老年人患轻度认知障碍的风险低 20%。研究人员解释说，这是因为蘑菇中含有一种特殊化合物一麦角硫因，因此，食用蘑菇有助于降低老年人患轻度认知障碍的风险。","prompt":"以下哪项如果为真,最能支持上述结论?","options":{"A":"研究发现,每周食用两次以上蘑菇的年轻人患心脏病的风险降低","B":"轻度认知障碍老年患者血浆中麦角硫因的水平明显低于同龄健康人","C":"上述研究中老年人主要食用的是金针菇、平菇等6种常见蘑菇","D":"人体实际上无法自行合成麦角硫因，只能从食物中获取"},"answer":"B","page":11},{"id":37,"chapter":1,"num":37,"source":"2021国考副省级","type":"逻辑判断","stem":"地质学家在澳大利亚中部距地表3 公里的地下发现了两处直径超过 200 公里的神秘自然景观，景观所含有的石英砂中有着一簇簇的细线，这些细线大部分是相互平行的直线，地质学家认为,这些景观很可能是巨大陨石撞击形成的陨石坑,而石英砂的结构就是造成断裂的证据。","prompt":"以下哪项是上述论证的必要前提？","options":{"A":"只有经历高速的陨石撞击,地层中石英砂才会显示出含有平行直线的断裂结构","B":"石英砂普遍存在于地球表面，由于坚硬、耐磨、化学性能稳定而很少发生变化","C":"该景观的直径之大，并不同于其他的陨石坑,很可能不是一次形成的","D":"该景观周围的岩石是3 亿年到 4.2 亿年之前形成的，那么撞击也应发生在那一时期"},"answer":"A","page":12},{"id":38,"chapter":1,"num":38,"source":"2021国考副省级","type":"逻辑判断","stem":"近年来,国家从药品生产、流通和销售各环节发力,频频出台降低药价的相关政策。但是，让不少患者感到疑惑的是，一方面是国家降低药价的政策不断出台，另一方面却是诸多常用药价格不断上涨。","prompt":"以下哪项如果为真,最能解释上述现象？","options":{"A":"价格下降的药品占大多数，价格上涨的药品占少数,因此从整体上来说,药品价格仍然是下降了","B":"常用进口药的需求增多，相关政策无法控制此类药品的价格上涨","C":"国家虽然出台了降低药价的政策，但是其影响要经过一段时间才能显现出来","D":"降低药价的政策可以有效控制药品市场中因制药原料涨价而导致的药价上涨"},"answer":"B","page":12},{"id":39,"chapter":1,"num":39,"source":"2021国考副省级","type":"逻辑判断","stem":"单位安排甲、乙、丙、丁、戊、己、庚、辛8人出差，他们恰好被安排在宾馆同一排左右相邻的8个房间。已知：\n①甲和丙中间隔着3人;\n②乙和己中间隔着2人;\n③丁在庚的左边,他们中间隔着2人;\n④辛和戊中间隔着1人。","prompt":"根据以上信息,按照从左到右的顺序，下列哪项是不可能的？","options":{"A":"丁在第一个房间","B":"丁在第二个房间","C":"丁在第三个房间","D":"丁在第四个房间"},"answer":"C","page":12},{"id":40,"chapter":1,"num":40,"source":"2021国考副省级","type":"逻辑判断","stem":"近日，有研究团队通过对44个反当动物物种的基因组测序研究，创建了一个反刍动物的系统进化树，从而解析大量反刍动物的演化史。结果揭示，在近10万年前，反刍动物种群发生大幅衰减,而这些种群数的减少与人类向非洲之外迁徙的时间相符。有人据此认为，这佐证了早期人类活动造成了反刍动物种群的衰减。","prompt":"以下哪项如果为真，最能质疑上述结论？","options":{"A":"反刍动物种群衰减后，植被愈加茂盛，为人类提供了更多食物","B":"反刍动物通常有角，在遇到人类攻击时能发挥一定的防御作用","C":"同一时期的马、驴等奇蹄目动物的种群也出现大幅衰减的现象","D":"同一时期大型猫科动物繁盛，它们大规模捕杀反刍动物"},"answer":"D","page":13},{"id":41,"chapter":2,"num":1,"source":"2022国考地市级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":14,"stemImages":["banks/zhenti304_imgs/p014_f01.webp"]},{"id":42,"chapter":2,"num":2,"source":"2022国考地市级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"D","page":14,"stemImages":["banks/zhenti304_imgs/p014_f02.webp"]},{"id":43,"chapter":2,"num":3,"source":"2022国考地市级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":14,"stemImages":["banks/zhenti304_imgs/p014_f03.webp"]},{"id":44,"chapter":2,"num":4,"source":"2022国考地市级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"A","page":14,"stemImages":["banks/zhenti304_imgs/p015_f01.webp"]},{"id":45,"chapter":2,"num":5,"source":"2022国考地市级","type":"图形推理","stem":"左图为给定的立体图形，将其从任一面剖开，下面哪一项不可能是该立体图形的截面？（注：原书误印为折纸盒题干，已据2022国考真题校订）","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":15,"stemImages":["banks/zhenti304_imgs/p015_f02.webp"]},{"id":46,"chapter":2,"num":6,"source":"2022国考地市级","type":"图形推理","stem":"下列纸盒的外表面展开图中，哪项折叠成的纸盒和其他三个不一样?","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"C","page":15,"stemImages":["banks/zhenti304_imgs/p015_f03.webp"]},{"id":47,"chapter":2,"num":7,"source":"2022国考地市级","type":"图形推理","stem":"左图给定的是由相同正方体堆叠而成的多面体，该多面体可以由①、②和③三个多面体组合而成，以下哪项能填入问号处?","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"D","page":15,"stemImages":["banks/zhenti304_imgs/p015_f04.webp"]},{"id":48,"chapter":2,"num":8,"source":"2022国考地市级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①④⑤，②③⑥","B":"①③⑤，②④⑥","C":"①②⑥，③④⑤","D":"①②④，③⑤⑥"},"answer":"A","page":15,"stemImages":["banks/zhenti304_imgs/p016_f01.webp"]},{"id":49,"chapter":2,"num":9,"source":"2022国考地市级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①⑤⑥，②③④","B":"①②④，③⑤⑥","C":"①②⑤，③④⑥","D":"①③④，②⑤⑥"},"answer":"C","page":16,"stemImages":["banks/zhenti304_imgs/p016_f02.webp"]},{"id":50,"chapter":2,"num":10,"source":"2022国考地市级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①②③，④⑤⑥","B":"①④⑤，②③⑥","C":"①②④，③⑤⑥","D":"①③⑥，②④⑤"},"answer":"D","page":16,"stemImages":["banks/zhenti304_imgs/p016_f03.webp"]},{"id":51,"chapter":2,"num":11,"source":"2022国考地市级","type":"定义判断","stem":"刑事科学技术是公安、司法机关依照刑事诉讼法的规定，应用现代科学技术的成果,收集、检验和鉴定与犯罪活动有关的物证,为侦查、起诉、审判工作提供线索和证据的专门技术。","prompt":"根据上述定义,下列没有体现刑事科学技术的是：","options":{"A":"通过核对公司台账、采购合同等文件资料，确定犯罪嫌疑人行贿的具体数额","B":"交通肇事伤亡案件中，根据车辆损毁情况推断车辆的接触点、行驶方向及事故成因","C":"应用声谱仪对手机录音与犯罪嫌疑人的语音进行声学特征分析，作出是否为同一人的判断","D":"对警犬识别出来的可疑物进行成分鉴定，判断嫌疑人所携带的物品是否为违禁品"},"answer":"A","page":16},{"id":52,"chapter":2,"num":12,"source":"2022国考地市级","type":"定义判断","stem":"归因不变性原则是指人们会寻找某一特定结果与特定原因之间的不变联系，如果某种特定原因在许多情境下总是与某种结果相伴。人们就会把特定结果归结于那一原因。归因折扣原则是指人们不完全相信某一现象的形成确是由于某种原因所导致，即某一特定原因在产生特定结果中的作用，如果存在其他似是而非的原因，应该“打折扣”。","prompt":"根据上述定义,两类归因原则均没有体现的是：","options":{"A":"电视广告中明星推销洗发水时，观众觉得她的一头秀发不完全是因为洗发水才有的","B":"在代理了诸多离婚案件后，律师小林统计发现离婚诉讼中大多数争议与财产纠纷有关","C":"创业失败总会使创业者背负债务，创业者小罗这几年债台高筑，朋友认为他一定是创业失败了","D":"对一系列盗窃案的分析显示，现场都出现过同一个男人，人们容易假定该男人就是犯罪嫌疑人"},"answer":"B","page":17},{"id":53,"chapter":2,"num":13,"source":"2022国考地市级","type":"定义判断","stem":"由于人类建设活动的破坏和干扰，生物群体原来连续成片的生活环境被割裂，形成分散的岛状甚至碎片状的生境。生境廊道是指连接破碎化生境并适宜生物生活、移动或扩散的通道，便于实现物种基因、能量、物质的流动。","prompt":"根据上述定义，下列不属于生境廊道的是:","options":{"A":"国家公园内，两棵参天古树跨过公路上方枝叶相连，金丝猴借助古树跨越公路，不同区域的金丝猴群可以保持接触","B":"某地将过去严重污染的河道改造为河滨公园，架设了多座拱桥，美化了环境,方便了交通，还吸引了大量鸟类来此栖息","C":"为了让野生象群在两个自然保护区之间迁移，管理者设计建成了迁移通道，避开村寨，并保证该区域范围内有丰富的水和食物资源","D":"为避免青藏铁路隔断藏羚羊迁徙路线，动物学家设计了桥梁下方、隧道上方及路基缓坡3种形式的野生动物通路"},"answer":"B","page":17},{"id":54,"chapter":2,"num":14,"source":"2022国考地市级","type":"定义判断","stem":"对于特定论域中的任意两个对象 A.b 而言，当对象 a 与对象b 之间具有关系 R时，对象b与对象a之间是否也具有关系R？基于此，对称性关系命题可分为正对称关系、反对称关系和半对称关系。（1）正对称关系：若对象a与b 之间具有关系 R，则对象b 与a 之间也具有关系 R;（2）反对称关系：若对象a与b 之间具有关系R，则对象b 与a之间一定不具有关系 R;（3）半对称关系：若对象a与b 之间具有关系 R,则对象b与a之间不一定具有关系R。根据上述定义，下列关系属于半对称关系的是:","prompt":"根据上述定义，下列关系属于半对称关系的是：","options":{"A":"学生之间的同学关系","B":"两个分数之间的小于关系","C":"人与人之间的帮助关系","D":"城市与城市之间的相邻关系"},"answer":"C","page":17},{"id":55,"chapter":2,"num":15,"source":"2022国考地市级","type":"定义判断","stem":"(2017副省)火力投射密度是指军事行动中军事部门在单位时间内的最大弹药发射量。它是现代军事学中衡量作战部队战斗力的重要指标之一。","prompt":"根据上述定义,以下属于通过增大火力投射密度来加强部队战斗力的是：","options":{"A":"某步兵师在普通士兵中选拔特等射手编入狙击班,进而能够更有效地杀伤敌人的有生力量","B":"某国将其部队列装的半自动步枪全部更换为全自动步枪,增加了子弹的发射频率","C":"某炮兵部队将原计划两小时的炮火掩护时间延长为三小时，更有效地杀伤了掩体中的敌人","D":"某军事科研单位研制出更先进的炮火定位系统,能够将火力打击的误差由半径 200 米缩小到50米"},"answer":"B","page":18},{"id":56,"chapter":2,"num":16,"source":"2022国考地市级","type":"定义判断","stem":"基因污染指原生物种基因库非预期或不受控制的基因流动，即外源基因通过转基因作物、外来入侵物种、家养动物等扩散到其他栽培作物或自然野生物种并成为后者基因的一部分。","prompt":"根据上述定义,下列没有体现出基因污染的是：","options":{"A":"某农场生产的大豆发现了转基因成分","B":"黑足猫是一种体型娇小但捕猎能力超强的野生猫,跑到野外的家猫和黑足猫交配后，生出血统不纯正的黑足猫，真正的黑足猫几近灭绝","C":"转基因 SL 玉米获批做动物饲料,SL 玉米只占某国玉米总产量的1%，但一年后该国22%的玉米样本被认定含有 SL 玉米基因","D":"某国开发出耐除草剂的转基因油菜,油菜出油率提高，但这种油菜种子能在土壤中休眠数年,因此成为其他作物中的“杂草”"},"answer":"D","page":18},{"id":57,"chapter":2,"num":17,"source":"2022国考地市级","type":"定义判断","stem":"回指是在语法描写中用来指一个语言单位（回指语）从先前某个已表达的单位或意义（先行语）得出自身释义的过程或结果。回指可分为直接回指和间接回指。直接回指是指回指语与先行语存在明显共指关系，回指语是对先行语的重复。间接回指是指回指语与先行语之间的关系不明显，必须通过特定语境进行判断才能确立。","prompt":"根据上述定义,下列加下划线部分所反映的先行语和回指语之间的关系属于直接回指的是：","options":{"A":"门口停着好些三轮车，许多车夫在那里闲站着","B":"这房子相当讲究，门是楠木做的","C":"要向前来参会的人表示感谢，人家来参会就是对我们的支持","D":"他午饭前来到餐馆点了一杯咖啡，服务员是一位意大利人"},"answer":"C","page":18},{"id":58,"chapter":2,"num":18,"source":"2022国考地市级","type":"定义判断","stem":"在生物学、医学及其子科学的研究中，对从通常的生物学环境中分离出的生物体组织成分进行体外研究的实验称为体外实验；在活体生物机体之中进行研究的实验称为体内实验。","prompt":"根据上述定义,下列属于体外实验的是:","options":{"A":"在光学显微镜下观察枯草杆菌是否具有鞭毛","B":"研究不同比例氮肥对玉米植株生长的影响","C":"在试管中观察药剂与某溶液的化学反应","D":"在培养皿中对卵子授精后观察受精卵的发育情况"},"answer":"D","page":19},{"id":59,"chapter":2,"num":19,"source":"2022国考地市级","type":"定义判断","stem":"按调查范围来看，可将调查分为全面调查和非全面调查。全面调查指的是一定范围内的情况普查;非全面调查是指从总体中抽取一部分对象进行情况调查，又可分为：根据随机原则选择样本的抽样调查和有意识选取若干样本进行的典型调查。","prompt":"根据上述定义,下列说法正确的是：","options":{"A":"对某市幼儿园所有儿童进行口腔卫生检查，这属于非全面调查","B":"对省内 1-3 年级的全体学生进行体育活动时间的调查，这属于非全面调查","C":"规模较大的前 30 所医学院校进行学生就业情况调查，这属于典型调查","D":"对某市中考数学成绩最好的几所学校进行调查，总结相关经验，这属于抽样调查"},"answer":"C","page":19},{"id":60,"chapter":2,"num":20,"source":"2022国考地市级","type":"定义判断","stem":"地球物理勘探是通过研究和观测各种地球物理场的变化来探测地层岩性、地质构造等地质条件的过程。由于组成地壳的不同岩层介质往往在密度、弹性、导电性等方面存在差异，这些差异将引起相应的地球物理场的局部变化，通过测量这些物理场的分布和变化特征,结合已知地质资料进行分析研究，就可以达到推断地质性状的目的。","prompt":"根据上述定义,下列不属于地球物理勘探的是:","options":{"A":"根据岩石和矿石导电性、电磁感应特性等来记录地层界面的深度和形态","B":"利用人工激发的地震波在弹性不同地层内的传播规律，了解水文地质的分布情况","C":"采集岩石样品，分析岩石内的微量元素，通过发现与矿化有关的原生异常来寻找矿床","D":"通过观测不同岩石引起的重力差异，判断地下地层的岩性及状态，确定沉积盆地范围"},"answer":"C","page":19},{"id":61,"chapter":2,"num":21,"source":"2022国考地市级","type":"类比推理","stem":"贸易摩擦：出口下滑","prompt":"","options":{"A":"商业垄断：市场失灵","B":"醉酒驾驶：例行检查","C":"行政处罚：违规生产","D":"职务犯罪：谋取私利"},"answer":"A","page":19},{"id":62,"chapter":2,"num":22,"source":"2022国考地市级","type":"类比推理","stem":"边防检查：走私","prompt":"","options":{"A":"科普宣传：迷信","B":"农药喷洒：除害","C":"个税申报：偷税","D":"手术治疗：患病"},"answer":"A","page":19},{"id":63,"chapter":2,"num":23,"source":"2022国考地市级","type":"类比推理","stem":"呼吸系统：生殖系统","prompt":"","options":{"A":"生产计划：年度计划","B":"观赏花卉：药用花卉","C":"水面舰艇：巡洋舰艇","D":"简渎公文：纸质公文"},"answer":"D","page":20},{"id":64,"chapter":2,"num":24,"source":"2022国考地市级","type":"类比推理","stem":"微型无人机：旋翼无人机","prompt":"","options":{"A":"热带植物：香料植物","B":"集体决策：个人决策","C":"形象思维：抽象思维","D":"开环系统：闭环系统"},"answer":"A","page":20},{"id":65,"chapter":2,"num":25,"source":"2022国考地市级","type":"类比推理","stem":"独幕剧：歌剧：话剧","prompt":"","options":{"A":"流行歌曲：通俗歌曲：现代歌曲","B":"自由体操：竞技体操：艺术体操","C":"远程面试：单独面试：小组面试","D":"顺序作业：流水作业：平行作业"},"answer":"C","page":20},{"id":66,"chapter":2,"num":26,"source":"2022国考地市级","type":"类比推理","stem":"青铜器物：商朝礼器：文化遗产","prompt":"","options":{"A":"科幻小说：微型小说：文学作品","B":"中式建筑：苏州园林：特色建筑","C":"仰韶文化：半坡遗址：华夏文明","D":"进口食品：速冻海鲜：冷冻食品"},"answer":"A","page":20},{"id":67,"chapter":2,"num":27,"source":"2022国考地市级","type":"类比推理","stem":"剪发：烫发剂：烫发","prompt":"","options":{"A":"催熟：防腐剂：防腐","B":"伐树：植树节：植树","C":"风蚀：碳酸钙：溶蚀","D":"镇痛：止痛药：止痛"},"answer":"A","page":20},{"id":68,"chapter":2,"num":28,"source":"2022国考地市级","type":"类比推理","stem":"城市公园：公共设施：休闲娱乐","prompt":"","options":{"A":"国宾礼炮：电子礼炮：国事庆祝","B":"升降舞台：露天剧场：演出空间","C":"云服务器：虚拟技术：信息备份","D":"医用口罩：卫生用品：过滤空气"},"answer":"D","page":20},{"id":69,"chapter":2,"num":29,"source":"2022国考地市级","type":"类比推理","stem":"国色天香 对于()相当于()对于 玉树临风","prompt":"","options":{"A":"面如冠玉;首蛾眉","B":"倾国倾城;明眸皓齿","C":"一表人才;仪表堂堂","D":"才高八斗;亭亭玉立"},"answer":"A","page":20},{"id":70,"chapter":2,"num":30,"source":"2022国考地市级","type":"类比推理","stem":"自然声源 对于()相当于()对于 煤炭","prompt":"","options":{"A":"人工声源;植物遗骸","B":"燕语莺声;矿石燃料","C":"传播介质;社区供暖","D":"物体振动;地质危害"},"answer":"B","page":20},{"id":71,"chapter":2,"num":31,"source":"2022国考地市级","type":"逻辑判断","stem":"最近，主打白噪音的助眠产品引起很多人的兴趣。有人认为，白噪音可以掩盖环境中干扰性的刺激,有助于促进睡眠、改善睡眠质量。但研究者对此持怀疑态度，认为白噪音可改善睡眠的研究证据不足，持续白噪音甚至会对睡眠造成影响。","prompt":"以下哪项如果为真,不能支持研究者的观点？","options":{"A":"持续暴露在白噪音下，听觉系统会不断将声音信号转换成神经信号，上传大脑，大脑会持续保持活跃，无法充分休息","B":"持续的白噪音会引起听力的损害，甚至会导致认知功能障碍，严重者还会导致失眠或嗜睡","C":"白噪音会使健康志愿者睡眠期间脑电波的循环交替模式显著改变，这意味着健康入睡眠结构受到干扰","D":"白噪音掩盖环境中干扰性的刺激，也会掩盖环境中有意义的声音，可能对人的生活甚至对生命造成威胁"},"answer":"D","page":21},{"id":72,"chapter":2,"num":32,"source":"2022国考地市级","type":"逻辑判断","stem":"动物实验发现，和处于寒冷环境的同等大小的小鼠相比，温暖环境小鼠的骨密度明显增强，很少出现骨质疏松。与此同时，温暖环境中小鼠的肠道菌群更为活跃,当把这些小鼠的肠道菌群移植到寒冷环境的小鼠肠道后，后者骨密度也增强了。由此可见,只要改善肠道菌群活性就可以增强骨密度。","prompt":"以下哪项如果为真，最能削弱上述论证？","options":{"A":"肠道中不是所有的细菌都会引起成骨细胞的增加，从而增加骨密度","B":"改善肠道菌群活性还须与生活环境和饮食习惯相结合才能增强骨密度","C":"改善肠道菌群活性对于年老小鼠增加骨密度的作用不十分明显","D":"接受菌群移植的小鼠若持续处于寒冷环境，骨密度会很快再次降低至原有水平"},"answer":"B","page":21},{"id":73,"chapter":2,"num":33,"source":"2022国考地市级","type":"逻辑判断","stem":"一家全国连锁珠宝店的 H 分店，去年在当地投放大量电梯促销广告。广告投放后，客流量 激增,净利润和前一年同期相比增长了 30%。可见电梯促销广告对于提高企业利润十分有效。假设 G、M、R、S 是与 H 分店规模、位置等具有可比性的其他 4 家分店，则下列最能削弱上述论证的是：","prompt":"","options":{"A":"G分店，去年没有投放电梯广告，利润比 H 分店更高","B":"M分店，去年选择投放了报纸广告，销售额同比提升了30%","C":"R分店,去年投放大量电梯广告，销售额却比H分店低","D":"S分店,去年投放大量电梯广告，利润同比下降了10%"},"answer":"D","page":21},{"id":74,"chapter":2,"num":34,"source":"2022国考地市级","type":"逻辑判断","stem":"熊蜂是一类多食性昆虫，与蜜蜂相比,熊蜂体型更大且多毛，颜色各异，大多有着经典的黄黑条纹,黑身红尾。人们发现,由于密集管理型农业系统的推广，熊蜂在这些地方开始衰落，有的种类已经灭绝，相对而言，普通蜜蜂的数量并没有明显减少。因此，相比普通蜜蜂，农田利用方式的改变对熊蜂的生存威胁更大。","prompt":"以下哪项如果为真，最能支持上述结论？","options":{"A":"蜜蜂采食会派出“侦查员\"，回来后通过一种“摆动舞\"告知蜂群食源在哪里，而熊蜂不会跳舞，因此大多独自采食","B":"蜜蜂会在蜂巢内储藏大量食物,熊蜂的蜂巢储存食物量较少，一旦出现食物短缺,熊蜂就会处于劣势","C":"蜜蜂属于大型化社群,而熊蜂属于小型化社群,这会导致基因分异度降低，更易受到寄生虫感染而大量死亡","D":"密集型农田往往种植单一植物,如果植物不是处于花期，熊蜂就会因无法如蜜蜂般进行远距离飞行而岌岌可危"},"answer":"D","page":21},{"id":75,"chapter":2,"num":35,"source":"2022国考地市级","type":"逻辑判断","stem":"不同的读者在阅读时，会对文章进行不同的加工编码，一种是浏览，从文章中收集观点和信息，使知识作为独立的单元输入大脑，称为线性策略;一种是做笔记,在阅读时会构建一个层次清晰的架构，就像用信息积木搭建了一个“金字塔”，称为结构策略。做笔记能够对文章的主要内 容进行标注，因此与单纯的浏览相比,做笔记能够取得更优的阅读效果。","prompt":"要使上述论证成立,还需基于以下哪一前提？","options":{"A":"阅读效果的好坏取决于能否在阅读时抓住要点","B":"用浏览的方式进行阅读属于知识加工的线性策略","C":"做笔记涉及到了更加复杂的认知加工过程","D":"与线性策略相比,结构策略能够让学习提升速度"},"answer":"A","page":22},{"id":76,"chapter":2,"num":36,"source":"2022国考地市级","type":"逻辑判断","stem":"下列各项中,哪一类商品不可能排在第一排？","prompt":"","options":{"A":"文具类","B":"酒类","C":"粮油类","D":"日用品类"},"answer":"C","page":22,"passageId":"zhenti304_ch2_36_40","passage":"某超市从前到后整齐排列着7个货架，放置着文具、零食、调料、日用品、酒、粮油和饮料7类商品，每类商品占据一排。已知：\n（1）酒类排在调料类之前;\n（2）文具类和调料类中间隔着3排;\n（3）粮油类在零食类之后，中间隔着2排;\n(4)日用品类紧挨着文具类前一排或者后一排。"},{"id":77,"chapter":2,"num":37,"source":"2022国考地市级","type":"逻辑判断","stem":"按照从前往后,下列哪项排列是可能的？","prompt":"","options":{"A":"文具类、零食类、日用品类、酒类、调料类、粮油类、饮料类","B":"零食类、文具类、日用品类、粮油类、饮料类、调料类、酒类","C":"日用品类、文具类、酒类、零食类、饮料类、调料类、粮油类","D":"日用品类、文具类、零食类、酒类、粮油类、调料类、饮料类"},"answer":"C","page":22,"passageId":"zhenti304_ch2_36_40","passage":"某超市从前到后整齐排列着7个货架，放置着文具、零食、调料、日用品、酒、粮油和饮料7类商品，每类商品占据一排。已知：\n（1）酒类排在调料类之前;\n（2）文具类和调料类中间隔着3排;\n（3）粮油类在零食类之后，中间隔着2排;\n(4)日用品类紧挨着文具类前一排或者后一排。"},{"id":78,"chapter":2,"num":38,"source":"2022国考地市级","type":"逻辑判断","stem":"零食类和文具类中间最多可能隔几排?","prompt":"","options":{"A":"2排","B":"3排","C":"4排","D":"5排"},"answer":"D","page":23,"passageId":"zhenti304_ch2_36_40","passage":"某超市从前到后整齐排列着7个货架，放置着文具、零食、调料、日用品、酒、粮油和饮料7类商品，每类商品占据一排。已知：\n（1）酒类排在调料类之前;\n（2）文具类和调料类中间隔着3排;\n（3）粮油类在零食类之后，中间隔着2排;\n(4)日用品类紧挨着文具类前一排或者后一排。"},{"id":79,"chapter":2,"num":39,"source":"2022国考地市级","type":"逻辑判断","stem":"如果零食类排在第1排，那么下列哪项中的两类商品不可能是相邻的两排?","prompt":"","options":{"A":"日用品类和酒类","B":"零食类和日用品类","C":"文具类和粮油类","D":"零食类和文具类"},"answer":"A","page":23,"passageId":"zhenti304_ch2_36_40","passage":"某超市从前到后整齐排列着7个货架，放置着文具、零食、调料、日用品、酒、粮油和饮料7类商品，每类商品占据一排。已知：\n（1）酒类排在调料类之前;\n（2）文具类和调料类中间隔着3排;\n（3）粮油类在零食类之后，中间隔着2排;\n(4)日用品类紧挨着文具类前一排或者后一排。"},{"id":80,"chapter":2,"num":40,"source":"2022国考地市级","type":"逻辑判断","stem":"如果饮料类排在第1排，则以下哪项是可能的？","prompt":"","options":{"A":"粮油类排在调料类前一排","B":"零食类排在文具类前一排","C":"日用品类排在文具类前一排","D":"酒类排在文具类前一排"},"answer":"B","page":23,"passageId":"zhenti304_ch2_36_40","passage":"某超市从前到后整齐排列着7个货架，放置着文具、零食、调料、日用品、酒、粮油和饮料7类商品，每类商品占据一排。已知：\n（1）酒类排在调料类之前;\n（2）文具类和调料类中间隔着3排;\n（3）粮油类在零食类之后，中间隔着2排;\n(4)日用品类紧挨着文具类前一排或者后一排。"},{"id":81,"chapter":3,"num":1,"source":"2023国考地市级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"A","page":24,"stemImages":["banks/zhenti304_imgs/p024_f01.webp"]},{"id":82,"chapter":3,"num":2,"source":"2023国考地市级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"C","page":24,"stemImages":["banks/zhenti304_imgs/p024_f02.webp"]},{"id":83,"chapter":3,"num":3,"source":"2023国考地市级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"A","page":24,"stemImages":["banks/zhenti304_imgs/p025_f01.webp"]},{"id":84,"chapter":3,"num":4,"source":"2023国考地市级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"C","page":25,"stemImages":["banks/zhenti304_imgs/p025_f02.webp"]},{"id":85,"chapter":3,"num":5,"source":"2023国考地市级","type":"图形推理","stem":"下图是给定的立体图形（大圆柱内的虚线部分为挖空部分），将其从任一面剖开，下面哪一项不可能是该立体图形的截面？","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"A","page":25,"stemImages":["banks/zhenti304_imgs/p025_f03.webp"]},{"id":86,"chapter":3,"num":6,"source":"2023国考地市级","type":"图形推理","stem":"将一张直角三角形形状的纸片进行两次折叠,展开后的折痕将该三角形分成如图所示的 a.b.c.d 四个部分，则两次折叠后的纸片投影面积为：","prompt":"","options":{"A":"b+d+c-a","B":"b+d-c","C":"b+c-a","D":"b+d-a"},"answer":"D","page":26,"stemImages":["banks/zhenti304_imgs/p026_f01.webp"]},{"id":87,"chapter":3,"num":7,"source":"2023国考地市级","type":"图形推理","stem":"左图为等大的3个灰色正方体和15个白色正方体组合成的多面体,其可以切割为①、②和③三个小多面体，问③代表的多面体可能是：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"A","page":26,"stemImages":["banks/zhenti304_imgs/p026_f02.webp"]},{"id":88,"chapter":3,"num":8,"source":"2023国考地市级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①③⑤，②④⑥","B":"①④⑥，②③⑤","C":"①③④，②⑤⑥","D":"①②④，③⑤⑥"},"answer":"D","page":26,"stemImages":["banks/zhenti304_imgs/p026_f03.webp"]},{"id":89,"chapter":3,"num":9,"source":"2023国考地市级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①⑤⑥，②③④","B":"①④⑥，②③⑤","C":"①②⑥，③④⑤","D":"①③④，②⑤⑥"},"answer":"B","page":26,"stemImages":["banks/zhenti304_imgs/p027_f01.webp"]},{"id":90,"chapter":3,"num":10,"source":"2023国考地市级","type":"图形推理","stem":"把下面六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①②⑤，③④⑥","B":"①②④，③⑤⑥","C":"①④⑤，②③⑥","D":"①③⑤，②④⑥"},"answer":"C","page":27,"stemImages":["banks/zhenti304_imgs/p027_f02.webp"]},{"id":91,"chapter":3,"num":11,"source":"2023国考地市级","type":"定义判断","stem":"微量鉴定是指运用物理学、化学和仪器分析等方法，通过对案件现场有关物质材料（材料特点多为体小量微、不易注意）的成分及其结构进行定性、定量分析，对检材的种类、检材和嫌疑样本的同类性和同一性进行鉴定。","prompt":"根据以上定义,下列涉及交通事故的鉴定属于微量鉴定的是：","options":{"A":"对车辆驾驶人采血，分析血液中的酒精含量，判断驾驶人是否存在酒后驾车嫌疑","B":"现场提取、检验受害人毛发、衣物纤维，认定受害人是否与嫌疑人车辆存在接触","C":"拆解车辆特定部位,查明车辆故障原因,用以鉴定其属于人为责任还是机械故障","D":"通过人体损伤程度检验，确定伤害损伤部位与交通事故伤害后果的关联程度"},"answer":"B","page":27},{"id":92,"chapter":3,"num":12,"source":"2023国考地市级","type":"定义判断","stem":"政策工具是指实现政策目标所要运用的手段与方法。政策工具可分为以下三种：(1)供给型政策工具,对政策目标起直接促进作用，通常体现政府的重要政策导向,包含资金、人才、设施、技术、信息等方面的有效支持;（2）需求型政策工具，对政策目标起到拉动作用，释放对政策目标的需求,减少外部干扰,包括服务外包、直接采购、国际交流与贸易管制等；（3）环境型政策工具,对政策目标起到间接促进作用，通常体现为通过目标、计划、法规、金融与税收等方式提供有利的政策环境，包括目标规划、金融服务、税收优惠、法规管制以及策略性措施等。","prompt":"根据上述定义,下列属于促进养老服务的需求型政策工具的是：","options":{"A":"政府向养老机构购买居家养老服务，为低保家庭 60 周岁以上失能老人提供服务","B":"政府提供资金建设社区食堂,解决失能、独居、空巢等老年人“舌尖养老\"难题","C":"政府鼓励技工院校开设老年服务与管理、健康服务与管理、护理等养老服务相关专业","D":"商务部发布《关于推动养老服务产业发展的指导意见》，提出打造养老服务品牌"},"answer":"A","page":28},{"id":93,"chapter":3,"num":13,"source":"2023国考地市级","type":"定义判断","stem":"民宿是指利用当地民居等相关闲置资源，经营用客房不超过4 层、建筑面积不超过 800平方米，主人参与接待,为游客提供体验当地自然、文化与生产生活方式的小型住宿设施。","prompt":"根据上述定义,下列属于民宿的是:","options":{"A":"王某在市中心有一套两居室的房子，过了马路就是知名的景区公园。王某将闲置房间租给那些节假日来旅游的家庭，并提供导游服务","B":"某家庭农场开发亲子休闲旅游业务，建设了农业科普、亲子游玩场所,为孩子和家长营造一处寓教于乐的乡村乐园","C":"李某通过某网上平台找到心仪城市的会员“交换\"旅行，即双方各自为对方提供住宿，住在对方家中深入体验当地的风土人情","D":"张某在古镇上有一所老宅。他和某平台签订合同，将老宅租给该平台运营。该平台将老宅装修,并提供完善的酒店式服务机制"},"answer":"A","page":28},{"id":94,"chapter":3,"num":14,"source":"2023国考地市级","type":"定义判断","stem":"背信规避是指当风险来源为另一个体而不是自然条件时，人们普遍更不愿意冒险，即在同等条件下,人们对于人为风险的规避程度高于对客观风险的规避程度，体现在人们面对人为风险时比面对客观风险时表现得更保守。","prompt":"根据上述定义,下列没有体现背信规避的是：","options":{"A":"在对客观题阅卷方式意愿的调查中，学生更愿意选择机器阅卷而非人工阅卷","B":"决定谁先开球时,双方球员都倾向于由裁判抛硬币决定而非裁判随机指定","C":"在老师打算指派一个人多承担一项任务时，同学们纷纷表示要抽签决定","D":"与老司机相比,坐新手司机开的车时，后排座上的乘客主动系安全带的更多"},"answer":"D","page":28},{"id":95,"chapter":3,"num":15,"source":"2023国考地市级","type":"定义判断","stem":"小中取大法是指在决策时，首先计算各方案在不同自然状态下的收益，并找出各方案在最差自然状态下的收益，然后进行比较，选择在最差自然状态下收益最大或损失最小的方案作为最终方案的一种决策方法。大中取大法是指在决策时，首先计算各方案在不同自然状态下的收益,并找出各方案在最好自然状态下的收益，然后进行比较，选择在最好自然状态下收益最大的方案作为最终方案的一种决策方法。\n更新生产线方案在不同情况下的收益\n单位：万元","prompt":"根据上述定义,分别使用小中取大法和大中取大法对上述方案进行决策，所选择的方案依次是：","options":{"A":"方案二和方案二","B":"方案二和方案一","C":"方案三和方案一","D":"方案三和方案二"},"answer":"D","page":29,"stemImages":["banks/zhenti304_imgs/p029_f01.webp"]},{"id":96,"chapter":3,"num":16,"source":"2023国考地市级","type":"定义判断","stem":"异业合作是指两个或两个以上不同行业的企业，通过分享市场营销中的资源，以达到降低成本、提高效率、增强市场竞争力等目的的一种营销策略。","prompt":"根据上述定义，下列体现了异业合作的是：","options":{"A":"某集团下属的两家餐饮公司通过公众号互推产品信息，提升了各自的品牌影响力","B":"某互联网公司和商业银行共同发行联名信用卡，办卡成员将享受更大购物优惠","C":"某日用品企业将不同尺寸的收纳盒组成套装促销，销量剧增，其他企业也纷纷效仿","D":"某运动品牌在奥运会期间推出绘有奥运标志的限量款球鞋，搭配赠送新奥运吉祥物"},"answer":"B","page":29},{"id":97,"chapter":3,"num":17,"source":"2023国考地市级","type":"定义判断","stem":"植物病害分为侵染性病害和非侵染性病害。侵染性病害是由病原物引起的，可以在植物个体间互相传染的病害;非侵染性病害是由于环境不良、营养元素不足等非生物因素造成的病害，由于没有病原物的侵袭，所以不会在植物间相互传染。\n根据上述定义,下列属于非侵染性病害的是:\n①需要微酸性生长环境的杜鹃花,种植在偏碱性土壤中,叶片会黄化\n②植株浇水过多,盆土积水后,由于植株根系缺氧，会导致植株萎\n③除草剂使用不当会引起西瓜苗嫩叶黄化,叶片枯焦，植株萎缩\n④灰葡萄孢真菌会引起番茄灰霉病，发病后造成番茄大量烂果","prompt":"","options":{"A":"仅①④","B":"仅①②","C":"仅①②③","D":"仅②③④"},"answer":"C","page":29},{"id":98,"chapter":3,"num":18,"source":"2023国考地市级","type":"定义判断","stem":"联合式构词法是由两个意义相同、相反或相对的词根联合起来构成新词的方法，在词内两个词根是平等的，没有主从、正副之分。","prompt":"根据上述定义,下列使用了联合式构词法的是：","options":{"A":"\"叮当”,因摹拟动作的声音而构成的词","B":"“椅子\",在单字“椅”后面附加“子\"而构成的词","C":"\"蹉跎\",由韵母相同的两个单字组合构成意义与单字无关的词","D":"\"开关\",由“开\"和“关\"两个单字组合而构成的词"},"answer":"D","page":30},{"id":99,"chapter":3,"num":19,"source":"2023国考地市级","type":"定义判断","stem":"细胞学检查是指对患者病变部位脱落、刮取或穿刺抽取的细胞，进行病理形态学的观察并做出定性诊断的检查方式。细胞学检查主要应用于肿瘤的诊断，也可用于某些疾病的检查和诊断,如内部器官炎症性疾病的诊断和激素水平的判定等。","prompt":"根据上述定义,下列属于细胞学检查的是：","options":{"A":"采集患者血液样本,分析血细胞比例变化，判断患者是否出现感染","B":"针对外伤患者皮肤纤维细胞的过度增生,实行激光打磨法,抑制炎性细胞浸润,修复再生皮肤组织","C":"通过拉网法收集食道癌患者的食道脱落细胞,鉴定细胞形态，明确癌变性质","D":"对脑疝患者脑室穿刺,放出脑室液以降低脑压,后再次穿刺注入造影剂,诊断其颅内占位病变的情况"},"answer":"C","page":30},{"id":100,"chapter":3,"num":20,"source":"2023国考地市级","type":"定义判断","stem":"预判设计是一种能够引导用户、缩短用户行为路径的有效设计手段。它可以根据用户的行为或用户所在的场景,让功能“主动找到\"用户，并让用户与之产生自然的交互，为用户提供更好的使用体验，本质就是为用户多想一步，让用户使用起来尽量简单。","prompt":"根据上述定义,下列不属于预判设计的是：","options":{"A":"某购物软件,根据用户输入的搜索关键词，将商品按与关键词的相关性排列","B":"某翻译软件,用户第一次点击播放，语音速度正常;再次点击，语音速度变慢","C":"某外卖软件,当用户对店家给出差评，系统自动勾选“将评价设为匿名评价”","D":"某购物软件,所选商品缺货时,出现“找相似\"按钮,点击可看到同款、相似商品"},"answer":"A","page":30},{"id":101,"chapter":3,"num":21,"source":"2023国考地市级","type":"类比推理","stem":"小计：总计","prompt":"","options":{"A":"平均值：总值·","B":"被乘数:总数","C":"单科分:总分","D":"分目录：总目"},"answer":"C","page":30},{"id":102,"chapter":3,"num":22,"source":"2023国考地市级","type":"类比推理","stem":"猛药去疴：重典治乱","prompt":"","options":{"A":"民生在勤:勤则不匮","B":"从善如登:从恶如崩","C":"静以修身：俭以养德","D":"名非天造:必从其实"},"answer":"C","page":30},{"id":103,"chapter":3,"num":23,"source":"2023国考地市级","type":"类比推理","stem":"强光照射：视力损伤","prompt":"","options":{"A":"台风过境：渔业停产","B":"网络招聘:业务扩张","C":"原油进口:能源紧缺","D":"风险防范:消防演练"},"answer":"A","page":31},{"id":104,"chapter":3,"num":24,"source":"2023国考地市级","type":"类比推理","stem":"铜镜：化妆镜","prompt":"","options":{"A":"门帘：纱帘","B":"木碗：汤碗","C":"金簪：发簪","D":"瓷瓶:古瓶"},"answer":"B","page":31},{"id":105,"chapter":3,"num":25,"source":"2023国考地市级","type":"类比推理","stem":"片剂：散剂:气雾剂","prompt":"","options":{"A":"边塞诗:山水诗：抒情诗","B":"口头契约:君子协定：书面协议","C":"泉水:湖水:天然水","D":"头部理疗：腰部理疗:腿部理疗"},"answer":"D","page":31},{"id":106,"chapter":3,"num":26,"source":"2023国考地市级","type":"类比推理","stem":"春季过敏:花粉：喷嚏","prompt":"","options":{"A":"肺炎:咳嗽：支原体","B":"乙型脑炎:病毒:发热","C":"失眠：恐惧：噩梦","D":"秋季腹泻:饮食：脱水"},"answer":"B","page":31},{"id":107,"chapter":3,"num":27,"source":"2023国考地市级","type":"类比推理","stem":"标清：高清：超清","prompt":"","options":{"A":"亚音速:音速：超音速","B":"厅级：市级：省级","C":"迁怒:愤怒：暴怒","D":"幽静:寂静：安静"},"answer":"A","page":31},{"id":108,"chapter":3,"num":28,"source":"2023国考地市级","type":"类比推理","stem":"资产评估：审核通过：股票发售","prompt":"","options":{"A":"预定新车:加装内饰：购买车险","B":"修剪草坪:设备检修：园林养护","C":"选购家电：上门安装：维修保养","D":"收看节目：视频连线：观众互动"},"answer":"C","page":31},{"id":109,"chapter":3,"num":29,"source":"2023国考地市级","type":"类比推理","stem":"深空探测 对于（)相当于（)对于 公益组织","prompt":"","options":{"A":"无人采样;慈善捐款","B":"遥感技术;红十字会","C":"宇宙空间;公益事业","D":"火星探测;社会组织"},"answer":"D","page":31},{"id":110,"chapter":3,"num":30,"source":"2023国考地市级","type":"类比推理","stem":"口不言对于（)相当于（)对于 虚怀若谷","prompt":"","options":{"A":"三其口;大智若愚","B":"畅所欲言；放荡不羁","C":"守口如瓶;礼贤下士","D":"口若悬河;矜功伐善"},"answer":"D","page":31},{"id":111,"chapter":3,"num":31,"source":"2023国考地市级","type":"逻辑判断","stem":"深度学习是一系列复杂的算法，使计算机能够识别数据中的模式并作出预测。研究人员利用深度学习技术训练 AI系统自动读取视网膜扫描数据,并识别那些在接下来的一年中患心脏病风险较高的人。研究人员认为该项技术有可能彻底改变传统的心脏病筛查方式。","prompt":"上述论证的成立须补充以下哪项作为前提？","options":{"A":"视网膜扫描数据反映的微小血管变化是预测心脏疾病较为灵敏的指标","B":"心脏病筛查需要进行复杂且昂贵的超声心动图或心脏磁共振成像检查","C":"视网膜扫描相对便宜，并且在许多配镜服务中被使用","D":"AI 系统是解开自然界中存在的复杂模式的绝佳工具"},"answer":"A","page":32},{"id":112,"chapter":3,"num":32,"source":"2023国考地市级","type":"逻辑判断","stem":"调查显示,某地区第二产业从业人员与五年前相比减少了10.4%,对于第二产业从业人员减少的原因，一种观点认为，产业优化升级是第二产业从业人员减少的原因，第二产业在实现产业规模快速扩大的同时，不断加快技术改造,实现“机器换工\",客观上降低了工业企业的用工需求。另一种观点则认为，这与第二产业的优化升级无关,第三产业的蓬勃发展发挥了就业“蓄水池\"的功能，吸纳了大量第二产业从业人员。","prompt":"以下哪项如果为真,最能削弱第二种观点？","options":{"A":"第二产业优化升级拉动了第三产业蓬勃发展","B":"该地区第三产业的整体规模比第二产业要小","C":"第三产业的发展得益于持续优化的营商环境","D":"第二产业和第三产业都对吸纳就业作出贡献"},"answer":"A","page":32},{"id":113,"chapter":3,"num":33,"source":"2023国考地市级","type":"逻辑判断","stem":"太平洋中部的海底，散落着大量的矿石,这些矿石名为“多金属结核”，是镍、钴、锰等稀有金属的混合物。支持深海开采的人认为，多金属结核可以提供开发清洁能源所需的矿物，同时海洋每年吸收约四分之一的全球碳排放量，开采结核的过程本身对海洋的碳吸收能力影响不大,反对者则认为海洋本就已经受到过度捕捞、工业污染和塑料垃圾等人类活动的威胁，在这种情况下,深海开采将加剧人类活动对海洋产生不利的影响。","prompt":"以下哪项如果为真,最能支持反对者的观点？","options":{"A":"目前人类对深海生物及环境的研究还不够深入，还不足以支持对深海进行大规模开采矿物的活动","B":"即使海洋开采活动能够为日益增加的能源需求提供更多的金属,人类对金属的需求仍然得不到满足,只会与日俱增","C":"地球上的海洋彼此相连,并共享一个环绕地球的洋流系统,开采活动的评估应该进行全局考虑","D":"深海开采过程中释放的泥浆会威胁矿区之上深海中层水域的生态环境,还会产生很大的噪音向上层水域扩散"},"answer":"D","page":32},{"id":114,"chapter":3,"num":34,"source":"2023国考地市级","type":"逻辑判断","stem":"传统污水处理,或通过重力沉降、混凝澄清、浮力浮上、离心力分离、磁力分离等物理方法对不溶态污染物进行分离，或通过酸碱中和法、化学沉淀法、氧化还原法等化学方法让污染物发生转化，而新兴的微生物治理技术则是通过水体微生物来净化污水。有专家认为，与传统手段相比，微生物治理技术是一种处理污水的更佳手段。","prompt":"以下哪项如果为真,不能支持上述观点？","options":{"A":"近年来，微生物技术的科研投入持续扩大，相关技术成果在土壤改良等领域已经得到了有效转化","B":"物理方法进行污水治理的处理厂，通常占地面积大,基建费、运行费高，能耗大,易出现污泥膨胀现象","C":"化学方法进行污水治理运行成本高，需消耗大量的化学试剂，易产生二次污染","D":"微生物技术污水治理的能耗低，效率高，剩余污泥量少，操作管理方便"},"answer":"A","page":33},{"id":115,"chapter":3,"num":35,"source":"2023国考地市级","type":"逻辑判断","stem":"近来，国际大宗商品市场中，原油和天然气价格达到近十年以来的高位，锌矿价格也上涨了7%左右，有分析人士认为，大宗商品市场将进入“超级周期”（大宗商品价格高于长期平均价格的时期）。从宏观层面看，大宗商品进入“超级周期\"是全球经济出现新的增长动力的结果。历史上大宗商品进入“超级周期\"往往会带动全球经济复苏，这也预示着当下全球经济正在复苏。","prompt":"以下哪项如果为真,最能削弱上述论证？","options":{"A":"地缘政治的风险加剧了大宗商品供应的紧张局势，引发本轮大宗商品价格上涨","B":"飙升的天然气价格推高了化肥的主要成分——氨的价格，进而推高全球粮食价格","C":"全球经济将更注重环保，碳中和与碳达峰将改变能源产业格局,进而影响金属和原油产业的发展远景","D":"全球主要经济体正在加紧出台强有力的救市计划，以寻求本国新的经济增长动力"},"answer":"A","page":33},{"id":116,"chapter":3,"num":36,"source":"2023国考地市级","type":"逻辑判断","stem":"关于6天中的人选，以下哪项安排符合上述条件？","prompt":"","options":{"A":"财务、人事、后勤、法务、财务、人事","B":"销售、财务、法务、人事、财务、销售","C":"人事、财务、法务、研发、法务、后勤","D":"法务、销售、人事、后勤、财务、销售"},"answer":"B","page":33,"passageId":"zhenti304_ch3_36_40","passage":"6天休假期间，单位需要每天安排一人值班。财务、研发、人事、后勤、法务和销售6个部门各推荐了2人，值班人员从这12人中选择，每人至多值班一天。安排要求：\n（1）第二天和第四天不安排法务部门的人值班;\n（2）若安排后勤部门的人值班，则只能安排在法务部门的人值班的前一天;\n（3）若安排研发部门的人值班，则只能安排在后勤部门的人值班的前一天。"},{"id":117,"chapter":3,"num":37,"source":"2023国考地市级","type":"逻辑判断","stem":"后勤部门的人可以安排在哪几天值班？","prompt":"","options":{"A":"只有第二天、第四天、第五天","B":"只有第一天、第三天、第五天","C":"只有第二天、第六天","D":"只有第一天、第三天"},"answer":"A","page":34,"passageId":"zhenti304_ch3_36_40","passage":"6天休假期间，单位需要每天安排一人值班。财务、研发、人事、后勤、法务和销售6个部门各推荐了2人，值班人员从这12人中选择，每人至多值班一天。安排要求：\n（1）第二天和第四天不安排法务部门的人值班;\n（2）若安排后勤部门的人值班，则只能安排在法务部门的人值班的前一天;\n（3）若安排研发部门的人值班，则只能安排在后勤部门的人值班的前一天。"},{"id":118,"chapter":3,"num":38,"source":"2023国考地市级","type":"逻辑判断","stem":"如果安排后勤部门的两人值班,则以下哪项一定是错误的？","prompt":"","options":{"A":"第一天安排研发部门的人值班","B":"第六天安排人事部门的人值班","C":"第三天安排财务部门的人值班","D":"第五天安排法务部门的人值班"},"answer":"C","page":34,"passageId":"zhenti304_ch3_36_40","passage":"6天休假期间，单位需要每天安排一人值班。财务、研发、人事、后勤、法务和销售6个部门各推荐了2人，值班人员从这12人中选择，每人至多值班一天。安排要求：\n（1）第二天和第四天不安排法务部门的人值班;\n（2）若安排后勤部门的人值班，则只能安排在法务部门的人值班的前一天;\n（3）若安排研发部门的人值班，则只能安排在后勤部门的人值班的前一天。"},{"id":119,"chapter":3,"num":39,"source":"2023国考地市级","type":"逻辑判断","stem":"如果在第三天、第五天分别安排两个财务部门的人值班，则第一天、第六天可安排的值班人员可能分别来自：","prompt":"","options":{"A":"后勤部门和法务部门","B":"法务部门和销售部门","C":"财务部门和销售部门","D":"研发部门和人事部门"},"answer":"B","page":34,"passageId":"zhenti304_ch3_36_40","passage":"6天休假期间，单位需要每天安排一人值班。财务、研发、人事、后勤、法务和销售6个部门各推荐了2人，值班人员从这12人中选择，每人至多值班一天。安排要求：\n（1）第二天和第四天不安排法务部门的人值班;\n（2）若安排后勤部门的人值班，则只能安排在法务部门的人值班的前一天;\n（3）若安排研发部门的人值班，则只能安排在后勤部门的人值班的前一天。"},{"id":120,"chapter":3,"num":40,"source":"2023国考地市级","type":"逻辑判断","stem":"如果没有安排财务和后勤部门的人值班，则以下哪项一定是正确的？","prompt":"","options":{"A":"第四天安排销售部门的人值班","B":"第五天安排法务部门的人值班","C":"第二天安排销售部门或者人事部门的人值班","D":"第三天安排法务部门或者人事部门的人值班"},"answer":"C","page":34,"passageId":"zhenti304_ch3_36_40","passage":"6天休假期间，单位需要每天安排一人值班。财务、研发、人事、后勤、法务和销售6个部门各推荐了2人，值班人员从这12人中选择，每人至多值班一天。安排要求：\n（1）第二天和第四天不安排法务部门的人值班;\n（2）若安排后勤部门的人值班，则只能安排在法务部门的人值班的前一天;\n（3）若安排研发部门的人值班，则只能安排在后勤部门的人值班的前一天。"},{"id":121,"chapter":4,"num":1,"source":"2024国考地市级","type":"图形推理","stem":"从所给的四个选项中,选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"C","page":35,"stemImages":["banks/zhenti304_imgs/p035_f01.webp"]},{"id":122,"chapter":4,"num":2,"source":"2024国考地市级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一项填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":35,"stemImages":["banks/zhenti304_imgs/p035_f02.webp"]},{"id":123,"chapter":4,"num":3,"source":"2024国考地市级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一项填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"D","page":35,"stemImages":["banks/zhenti304_imgs/p035_f03.webp"]},{"id":124,"chapter":4,"num":4,"source":"2024国考地市级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一项填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":35,"stemImages":["banks/zhenti304_imgs/p036_f01.webp"]},{"id":125,"chapter":4,"num":5,"source":"2024国考地市级","type":"图形推理","stem":"左图为13个白色正方体和5个灰色正方体组合而成的多面体，现用经 A.B.C三个顶点的平面对该多面体进行切割,正确的截面是:","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":36,"stemImages":["banks/zhenti304_imgs/p036_f02.webp"]},{"id":126,"chapter":4,"num":6,"source":"2024国考地市级","type":"图形推理","stem":"左图为15个白色正方体和3个灰色正方体组合而成的多面体，其可以由①、②、③三个多面体组合而成，问哪项能填入问号处？","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"A","page":36,"stemImages":["banks/zhenti304_imgs/p036_f03.webp"]},{"id":127,"chapter":4,"num":7,"source":"2024国考地市级","type":"图形推理","stem":"左图为8个白色正方体和4个黑色正方体粘接而成的长方体，问以下哪一个不可能是其外表面展开图？","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"D","page":36,"stemImages":["banks/zhenti304_imgs/p037_f01.webp"]},{"id":128,"chapter":4,"num":8,"source":"2024国考地市级","type":"图形推理","stem":"把下面六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①②⑥，③④⑤","B":"①③④，②⑤⑥","C":"①③⑥，②④⑤","D":"①③⑤，②④⑥"},"answer":"C","page":37,"stemImages":["banks/zhenti304_imgs/p037_f02.webp"]},{"id":129,"chapter":4,"num":9,"source":"2024国考地市级","type":"图形推理","stem":"把下面六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①④⑤，②③⑥","B":"①③④，②⑤⑥","C":"①⑤⑥，②③④","D":"①②⑥，③④⑤"},"answer":"C","page":37,"stemImages":["banks/zhenti304_imgs/p037_f03.webp"]},{"id":130,"chapter":4,"num":10,"source":"2024国考地市级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①②⑥，③④⑤","B":"①④⑥，②③⑤","C":"①③⑤，②④⑥","D":"①②③，④⑤⑥"},"answer":"D","page":37,"stemImages":["banks/zhenti304_imgs/p038_f01.webp"]},{"id":131,"chapter":4,"num":11,"source":"2024国考地市级","type":"定义判断","stem":"多级养殖是指根据物种代谢产物或残余有机质的利用价值及其在食物链中所处的级次，依次放养相应生物,多级次利用营养物质的一种养殖方式。","prompt":"根据上述定义,下列属于多级养殖的是：","options":{"A":"将养殖过江篱的海水用于放养贝类,以利用其中繁殖的浮游生物;再将养殖过贝类的水用于放养对虾;再以对虾代谢分解的产物养殖藻类","B":"将鱼、虾、贝类与藻类放在同一水槽混养，其代谢产物会为藻类提供必要的营养要素，藻类的光合作用又产生更多的溶解氧","C":"在一台浮筏上,于冬春季养殖海带;至夏秋季养殖海湾扇贝或石花菜，从而更好利用海况条件，满足市场需要","D":"同一池塘中，鲢、鳙生活在上层，主食浮游生物；草鱼、蝙生活在中下层，主食草类;鲤、鲫生活在底层，主食底栖动物和有机碎屑"},"answer":"A","page":38},{"id":132,"chapter":4,"num":12,"source":"2024国考地市级","type":"定义判断","stem":"复杂型消费行为是指消费者对价格昂贵,品牌差异大，功能复杂的商品，由于缺乏必要的商品知识,需要慎重选择,仔细对比,只求降低风险的购买行为;多变型消费行为是指如果消费者购买的商品价格低，可供选择的品牌很多时，他们并不花太多的时间选择品牌,而是经常变换品牌。","prompt":"根据上述定义,下列说法正确的是：","options":{"A":"老李给儿子换了十几个钢琴老师之后，发现还是第一个钢琴老师最好，于是一次性交了一年的学费。这属于复杂型消费行为","B":"小明去超市买某品牌饼干，心想上次买了巧克力口味，这次买绿茶口味，下次再试一下夹心的。这属于多变型消费行为","C":"老王打算买一辆越野车，网上查阅了各种型号参数，试驾了十几款品牌之后，才做出决定。这属于复杂型消费行为","D":"小丽逛街的时候本来只想买一条裤子，后来发现需要搭配一件合适的上衣和配套的手提包，所以买了全套。这属于多变型消费行为"},"answer":"C","page":38},{"id":133,"chapter":4,"num":13,"source":"2024国考地市级","type":"定义判断","stem":"慢病也称为慢性非传染性疾病，是指长期的、不能自愈的、也几乎不能被治愈的疾病。慢病自我管理是指慢病患者主动监测自己的病情，以积极态度及行动，改善健康和情绪,通过对疾病的认识，学习与疾病长期共存。","prompt":"根据上述定义,下列属于慢病自我管理的是：","options":{"A":"老张在患了流感后多方查阅相关信息，每天监测血氧、心率、血压等指标，不做剧烈运动，避免着凉","B":"老王因慢性肾功能衰竭需定期在医院进行透析治疗，医院为其建立了慢病管理档案,追踪监测肾功能等各项指标","C":"老赵的父母都因胃癌去世，老赵深知该疾病的严重后果，每年全面体检一次，定期进行胃肠镜检查,不熬夜不喝酒,规律作息","D":"患ⅡI型糖尿病的老李，平日生活格外谨慎，含糖量高的食物一概不碰，每天按时服药，定期监测血糖水平"},"answer":"D","page":39},{"id":134,"chapter":4,"num":14,"source":"2024国考地市级","type":"定义判断","stem":"人际关系图，是用一套特定的符号来表示团体内成员之间各种关系的图形。依据前期的调查，将团体成员的关系分为吸引\"排斥\"无关\"三类。图中圆圈内的字母是团体内每一成员的代号。实线与虚线表示相互关系，其中实线表示吸引关系，虚线表示排斥关系，箭头表示方向（例如：①→表示 A受B吸引，-→表示 A排斥 B），其中被实线箭头指向最多的人，就是处于团体中心位置的人。","prompt":"根据上述定义，对下图的判断正确的是：","options":{"A":"该团体中没有相互排斥的人","B":"C 是处于团体中心位置的人","C":"F 是该团体中受排斥最多的人","D":"H和 B 是相互吸引的人"},"answer":"A","page":39,"stemImages":["banks/zhenti304_imgs/p039_f01.webp"]},{"id":135,"chapter":4,"num":15,"source":"2024国考地市级","type":"定义判断","stem":"电子测量是指利用电子技术为测量手段，进行电的或非电的各种测量，主要分两类：电参量的测量，是指对用电设备中用电参数的测量;非电参量的测量,是指通过不同类型的传感器将物理的、化学的、机械的非电参量转换成电信号,然后利用电子技术测出其相应的电参量，最后将其折合成非电参量数据。","prompt":"根据上述定义,下列电子测量与其他三项类型不同的是：","options":{"A":"利用电子仪表测量某机房电路的电压、电流","B":"用电子天平称出物体的重量","C":"声波使话筒内的驻极体薄膜振动，产生随之变化的电压，这一电压被数据采集器接收，用于测量声音的振动频率","D":"将电极放到体表采集患者心脏活动的电信号，经过放大传输到机器后形成心电图"},"answer":"A","page":40},{"id":136,"chapter":4,"num":16,"source":"2024国考地市级","type":"定义判断","stem":"总被引频次是指期刊自创刊以来登载的全部论文在统计当年被引用的总次数。扩散因子是一个用于评估期刊影响力的学术指标，显示总被引频次扩散的范围,具体意义为期刊当年每被引100 次所涉及的期刊数，即扩散因子=总被引频次涉及的期刊数×总被引频次。\n甲刊：创刊于1980年，2022年总被引频次为2000，涉及期刊 800种\n乙刊:创刊于2000年，2022年总被引频次为1500，涉及期刊500种\n丙刊：创刊于2020年，2022年总被引频次为200，涉及期刊60种","prompt":"根据定义，在2022年，上述三种期刊按照扩散因子由大到小排序正确的是:","options":{"A":"丙、甲、乙","B":"丙、乙、甲","C":"乙、丙、甲","D":"甲、乙、丙"},"answer":"D","page":40},{"id":137,"chapter":4,"num":17,"source":"2024国考地市级","type":"定义判断","stem":"动态描写法是指记叙文中对人物、景物作运动状态的描写，创造具体而栩栩如生的形象的一种描写方法。动态描写法包括两类:一类是对运动着的景物的描写，一类是对静物所作的动态描写。动态描写法的目的在于赋予客观事物以运动感、活力感、变化感，克服形象的单调性,丰富形象的多样性,达到更好地表现事物、感染读者的艺术效果。","prompt":"根据上述定义,下列没有体现动态描写法的是：","options":{"A":"有的松树望穿秋水,不见你来，独自上到高处，斜着身子张望","B":"夜阑人静,家养的大黄狗趴在院子里安静地睡了","C":"七股大水,从水库的桥孔跃出，仿佛七幅闪光的黄锦，直铺下去","D":"一轮杏黄色的满月，悄悄从山嘴处爬出来,把倒影投入湖水中"},"answer":"B","page":40},{"id":138,"chapter":4,"num":18,"source":"2024国考地市级","type":"定义判断","stem":"附性法推理是指将同一属性分别附加在原命题的主项和谓项前面，从而形成一个新命题的推理方法,以公式表示即为：“所有S（主项）是P（谓项）→所有NS是NP”（其中\"N”表示某种属性）。运用这种推理必须遵守的规则是:①原命题必须断定了某个类别的所有事物的某种共性；②附加的属性概念必须保持含义的同一;③结论中的主谓项关系应与前提中的主谓项关系相同。","prompt":"根据上述定义,下列符合附性法推理规则的是：","options":{"A":"蝴蝶是昆虫,所以，色彩斑斓的蝴蝶是色彩斑斓的昆虫","B":"教师是人,所以，老教师是老人","C":"有些诗人是画家，所以，有些女诗人是女画家","D":"音乐家是人,所以，无天赋的音乐家是无天赋的人"},"answer":"A","page":40},{"id":139,"chapter":4,"num":19,"source":"2024国考地市级","type":"定义判断","stem":"中医七方指的是大方、小方、缓方、急方、奇方、偶方、复方七种方剂的总称。其中缓方是指药性缓和，治疗病势缓慢需长期服用的方剂;急方是指药性峻猛，治疗病势急重急于取效的方剂;奇方是指单数药物组成的方剂;偶方是指双数药物组成的方剂。","prompt":"根据上述定义,下列既属于缓方又属于偶方的是：","options":{"A":"参附汤：人参15克、附子 30克，有回阳、益气、固脱之功，常用于元气大亏、阳气暴脱之症","B":"甘草汤:甘草6克,主治少阴咽痛,兼治舌肿,有清热解毒之功效","C":"四君子汤：人参、甘草、茯苓、白术各等分，主治脾胃气虚证，症见面色萎黄、语声低微、气短乏力等","D":"生脉散:人参9克、麦门冬9克、五味子6克，为补益剂,具有益气生津、敛阴止汗之功效"},"answer":"C","page":41},{"id":140,"chapter":4,"num":20,"source":"2024国考地市级","type":"定义判断","stem":"在图书馆统计指标中，文献流通数是指实际被阅读者借阅、利用的文献数。文献流通率是指文献流通数与馆藏中提供流通的文献数的比率。文献利用率是指文献流通数与馆藏文献总数的比率。文献拒借率是指读者未能借到的文献数与读者合理要求借阅的文献数的比率，即索书条拒借数占索书条总数的百分比。文献保障率是指图书馆提供读者借阅、利用的文献数与图书馆拥有的读者数的比率。","prompt":"根据上述定义，下列说法正确的是：","options":{"A":"对一个图书馆来说，文献流通率一定不低于文献利用率","B":"对一个图书馆来说，文献流通率反映了图书馆馆藏文献的规模及读者的需求","C":"当文献拒借率越高时，文献保障率就越低","D":"文献流通数越多而馆藏中提供流通的文献数越少，文献利用率就越高"},"answer":"A","page":41},{"id":141,"chapter":4,"num":21,"source":"2024国考地市级","type":"类比推理","stem":"卫冕：夺冠","prompt":"","options":{"A":"庄园：田园","B":"追讨：诉讼","C":"续约:签约","D":"姓名:笔名"},"answer":"C","page":41},{"id":142,"chapter":4,"num":22,"source":"2024国考地市级","type":"类比推理","stem":"花生壳:核桃仁","prompt":"","options":{"A":"刺梨汁:桃花扇","B":"丝瓜络:石榴籽","C":"杏仁露：葡萄皮","D":"葛根茶:芡实粉"},"answer":"B","page":42},{"id":143,"chapter":4,"num":23,"source":"2024国考地市级","type":"类比推理","stem":"诛禁不当:反受其央","prompt":"","options":{"A":"为者常成：行者常至","B":"君子检身：常若有过","C":"其身不正:虽令不从","D":"麻雀虽小:五脏俱全"},"answer":"C","page":42},{"id":144,"chapter":4,"num":24,"source":"2024国考地市级","type":"类比推理","stem":"明辨是非:静待成败","prompt":"","options":{"A":"判若云泥:开释左右","B":"洞鉴古今：博观始终","C":"一争高低：弱肉强食","D":"惩恶劝善:天差地别"},"answer":"B","page":42},{"id":145,"chapter":4,"num":25,"source":"2024国考地市级","type":"类比推理","stem":"蚜虫：七星瓢虫:小麦","prompt":"","options":{"A":"蛇:鸟：谷子","B":"稗草:螳螂：水稻","C":"蚊子:青蛙：高梁","D":"老鼠：黄鼬：玉米"},"answer":"D","page":42},{"id":146,"chapter":4,"num":26,"source":"2024国考地市级","type":"类比推理","stem":"感想：主观性：体会","prompt":"","options":{"A":"典范：示范性：表率","B":"发明：创造性：方法","C":"泥土:可塑性：材料","D":"规律:普适性：定理"},"answer":"A","page":42},{"id":147,"chapter":4,"num":27,"source":"2024国考地市级","type":"类比推理","stem":"自发裂变:核裂变:诱发裂变","prompt":"","options":{"A":"波浪能:太阳能：可再生能源","B":"铁路交通:现代交通：公路交通","C":"贸易逆差：贸易平衡：贸易顺差","D":"负有理数:负实数：负无理数"},"answer":"D","page":42},{"id":148,"chapter":4,"num":28,"source":"2024国考地市级","type":"类比推理","stem":"轮作休耕:耕地保护:严禁占用","prompt":"","options":{"A":"植树造林:碳中和：节能减排","B":"登月计划：空间站：太空探索","C":"商品交换:国际贸易：技术服务","D":"观众评选：荣获大奖:出类拔萃"},"answer":"A","page":42},{"id":149,"chapter":4,"num":29,"source":"2024国考地市级","type":"类比推理","stem":"领头雁 对于()相当于()对于 先驱","prompt":"","options":{"A":"领导者;拓荒牛","B":"鸟类;革命","C":"迁徙;先锋","D":"出头鸟;先行者"},"answer":"A","page":42},{"id":150,"chapter":4,"num":30,"source":"2024国考地市级","type":"类比推理","stem":"重型战机 对于()相当于()对于 分辨率","prompt":"","options":{"A":"隐形战机 清晰度","B":"战斗机 性能指标","C":"轻型战机 订单量","D":"载弹量 显示器"},"answer":"D","page":42},{"id":151,"chapter":4,"num":31,"source":"2024国考地市级","type":"逻辑判断","stem":"冰雪旅游是利用冰雪气候资源体验冰雪文化的旅游活动，包括冰雪观光演艺、运动竞技等内容。H地区冰雪旅游开展了五年，调查显示：在近万名受访者中，有90%的人曾以不同形式体验过冰雪旅游，平均每年有 65%的人体验过1-2 次冰雪旅游，有 25%的人体验过3-4次，且这一比例逐年升高。这说明H地区冰雪旅游的需求较高，常态化多次消费正成为H地区越来越多人的选择。","prompt":"以下哪项如果为真，最能削弱上述结论？","options":{"A":"参与调查的受访者几乎都是了解或喜爱冰雪旅游的年轻人","B":"近五年，H地区冰雪旅游产业的年均投资额接近,没有增加","C":"H地区位于北半球北部，冬季较长，许多游客会来此体验冰雪旅游","D":"为扩大宣传，H地区许多冰雪项目会推出优惠组合套餐，吸引人们多次消费"},"answer":"A","page":43},{"id":152,"chapter":4,"num":32,"source":"2024国考地市级","type":"逻辑判断","stem":"多重宇宙理论通常也称为平行宇宙理论，该理论认为有无数个宇宙与我们所在的宇宙并存，虽然我们无法意识到这一点。这些宇宙可能与我们所处的宇宙截然不同，但也可能与我们的宇宙极其相似，在更广的意义上,要证明多重宇宙存在远比单纯想象它困难得多。甚至从一开始，有一部分科学家就认为这个理论称不上是“真正意义上的科学”。因为没有人能证明多重宇宙理论是错误的——即它无法被证伪。","prompt":"以下哪项可能是上述科学家论证的前提?","options":{"A":"平行宇宙理论至今未获证实，只是单纯的想象","B":"只有能被证伪的理论，才能称得上是“真正意义上的科学”","C":"平行宇宙理论即使变成现实，对于人类的文明进步也未必是坏事","D":"如果平行宇宙的数量足够多，那可能意味着在我们认为的虚拟世界中发生的事情也会真实地发生在平行宇宙中"},"answer":"B","page":43},{"id":153,"chapter":4,"num":33,"source":"2024国考地市级","type":"逻辑判断","stem":"在过去，药物的研发主要来自于陆地生物，这与陆地生物更被熟知且容易获得有关。近几十年来，越来越多的药物开始从海洋生物中产生，海洋生态环境极具复杂性，因而海洋生物相比于陆地生物有着更为广泛的多样性。有人据此认为，海洋生物产业潜力巨大，海洋生物更有可能是未来新型抗生素、抗癌药物的来源。","prompt":"以下除哪项外,均能支持上述观点？","options":{"A":"目前抗生素都来源于陆地微生物，病菌耐药性不断上升，而海洋微生物药物已经对一些感染性疾病提供了替代性疗法","B":"借助计算机工具,人们已经将庞大的生物基因组库和具有生物活性的化合物库进行关联，用以探索新药物","C":"一些海洋生物如鲸、鲨等终身不得癌症,有近 300 种海洋生物含有抗肿瘤物质，它们是研究抗癌药物的重要资源","D":"当前已经发现的3.5万个海洋天然产物中有一半以上都具有生物活性,还有更多数以万计的未知海洋天然产物亟待开发"},"answer":"B","page":43},{"id":154,"chapter":4,"num":34,"source":"2024国考地市级","type":"逻辑判断","stem":"研究中，实验组小鼠每天晚上接受两小时的蓝光照射，对照组小鼠白天接受两个小时的蓝光照射。三周之后,所有小鼠进行“强迫游泳\"和“糖水偏好\"测试。这两项测试常用来检测小鼠是否出现了类似抑郁的症状。结果发现，相比于白天接受光照的小鼠，夜间接受光照的小鼠明显表现出类似抑郁的症状。研究者认为，长期在夜间暴露于蓝光下，人们出现抑郁情绪的风险会提高。","prompt":"以下除哪项外,均能削弱研究者的观点？","options":{"A":"小鼠与人的生活习性完全不同，小鼠昼伏夜出,而人类基本是白天活动，晚上休息","B":"光对于小鼠是厌恶型刺激，小鼠回避光以降低被发现和捕食的风险，而人通常在光明的环境感觉更加安全","C":"行为测试是否能够测试主观情绪体验，类似抑郁的症状是否等同于出现抑郁的情绪体验，尚存在争议","D":"相比白天,夜间的光照更容易通过视网膜神经节细胞激活伏隔核，该脑区与负性情绪的产生有关"},"answer":"D","page":44},{"id":155,"chapter":4,"num":35,"source":"2024国考地市级","type":"逻辑判断","stem":"研究发现，一种被称为 EPAS1 的特殊基因能调节机体生理状态,使人类适应缺氧环境。考古研究表明这种特殊基因最早可追溯至16 万年前已居住于青藏高原的古人类。由于16万年前全国同时生活着尼安德特人、丹尼索瓦人及古老的直立人，其中只有丹尼索瓦人拥有这一基因，考古学家推测丹尼索瓦人很有可能在16 万年前居住于青藏高原。","prompt":"以下除哪项外,均能支持考古学家的推测？","options":{"A":"通过对牙齿形态的扫描，发现青藏高原古人类的牙齿齿列和丹尼索瓦人最为相似","B":"分析青藏高原人骨化石中的蛋白质序列,发现这些人类与丹尼索瓦人同属一类","C":"考古人员在青藏高原东北部的白石崖溶洞遗址提取到丹尼索瓦人的线粒 DNA","D":"丹尼索瓦人曾在亚洲广泛分布，他们曾在西伯利亚生活过,可耐受高寒环境"},"answer":"D","page":44},{"id":156,"chapter":4,"num":36,"source":"2024国考地市级","type":"逻辑判断","stem":"下列哪项是可能的先后依次结对的城市名单？","prompt":"","options":{"A":"甲和丙，丁和戊，乙和己","B":"丙和丁,甲和乙，戊和己","C":"丁和己,丙和戊，甲和乙","D":"丙和戊,甲和丁，乙和己"},"answer":"C","page":45,"passageId":"zhenti304_ch4_36_40","passage":"有甲、乙、丙、丁、戊、己6个城市，其中的两个城市在2021年结成一对友好城市，其余4个城市中的2个\n在 2022 年结成一对友好城市，剩余的2个城市在 2023 年也结成一对友好城市，已知：\n（1）乙的结对城市不是丁\n（2）甲的结对城市不是乙就是丙\n（3）甲和乙均不是在 2021年结对的\n（4）丁和戊均不是在 2023 年结对的"},{"id":157,"chapter":4,"num":37,"source":"2024国考地市级","type":"逻辑判断","stem":"如果己是2023年结对的，那么戊一定是和哪个城市结对的？","prompt":"","options":{"A":"甲","B":"乙","C":"丙","D":"丁"},"answer":"D","page":45,"passageId":"zhenti304_ch4_36_40","passage":"有甲、乙、丙、丁、戊、己6个城市，其中的两个城市在2021年结成一对友好城市，其余4个城市中的2个\n在 2022 年结成一对友好城市，剩余的2个城市在 2023 年也结成一对友好城市，已知：\n（1）乙的结对城市不是丁\n（2）甲的结对城市不是乙就是丙\n（3）甲和乙均不是在 2021年结对的\n（4）丁和戊均不是在 2023 年结对的"},{"id":158,"chapter":4,"num":38,"source":"2024国考地市级","type":"逻辑判断","stem":"如果丁是2022年结对的，那么下列各项中，哪两个城市可能结对？","prompt":"","options":{"A":"丙和戊","B":"乙和己","C":"甲和戊","D":"乙和戊"},"answer":"A","page":45,"passageId":"zhenti304_ch4_36_40","passage":"有甲、乙、丙、丁、戊、己6个城市，其中的两个城市在2021年结成一对友好城市，其余4个城市中的2个\n在 2022 年结成一对友好城市，剩余的2个城市在 2023 年也结成一对友好城市，已知：\n（1）乙的结对城市不是丁\n（2）甲的结对城市不是乙就是丙\n（3）甲和乙均不是在 2021年结对的\n（4）丁和戊均不是在 2023 年结对的"},{"id":159,"chapter":4,"num":39,"source":"2024国考地市级","type":"逻辑判断","stem":"如果甲和丙结对，下列哪一项一定为真？","prompt":"","options":{"A":"丙是 2023 年结对的","B":"已是 2023年结对的","C":"丁是 2021 年结对的","D":"戊是2021年结对的"},"answer":"C","page":45,"passageId":"zhenti304_ch4_36_40","passage":"有甲、乙、丙、丁、戊、己6个城市，其中的两个城市在2021年结成一对友好城市，其余4个城市中的2个\n在 2022 年结成一对友好城市，剩余的2个城市在 2023 年也结成一对友好城市，已知：\n（1）乙的结对城市不是丁\n（2）甲的结对城市不是乙就是丙\n（3）甲和乙均不是在 2021年结对的\n（4）丁和戊均不是在 2023 年结对的"},{"id":160,"chapter":4,"num":40,"source":"2024国考地市级","type":"逻辑判断","stem":"有几个城市可能是在 2022年与其他城市结对的？","prompt":"","options":{"A":"6个","B":"5个","C":"4个","D":"3个"},"answer":"A","page":45,"passageId":"zhenti304_ch4_36_40","passage":"有甲、乙、丙、丁、戊、己6个城市，其中的两个城市在2021年结成一对友好城市，其余4个城市中的2个\n在 2022 年结成一对友好城市，剩余的2个城市在 2023 年也结成一对友好城市，已知：\n（1）乙的结对城市不是丁\n（2）甲的结对城市不是乙就是丙\n（3）甲和乙均不是在 2021年结对的\n（4）丁和戊均不是在 2023 年结对的"},{"id":161,"chapter":5,"num":1,"source":"2025国考副省级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"D","page":46,"stemImages":["banks/zhenti304_imgs/p046_f01.webp"]},{"id":162,"chapter":5,"num":2,"source":"2025国考副省级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一项填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":46,"stemImages":["banks/zhenti304_imgs/p046_f02.webp"]},{"id":163,"chapter":5,"num":3,"source":"2025国考副省级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"D","page":46,"stemImages":["banks/zhenti304_imgs/p046_f03.webp"]},{"id":164,"chapter":5,"num":4,"source":"2025国考副省级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"A","page":46,"stemImages":["banks/zhenti304_imgs/p047_f01.webp"]},{"id":165,"chapter":5,"num":5,"source":"2025国考副省级","type":"图形推理","stem":"左边为15 个白色和3个灰色正方体组合而成多面体的正、反两面直观图，其可以由①、②和③三个多面体组合而成，问哪一项能填入问号处？","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":47,"stemImages":["banks/zhenti304_imgs/p047_f02.webp"]},{"id":166,"chapter":5,"num":6,"source":"2025国考副省级","type":"图形推理","stem":"下图为4个黑色、8个白色正方体粘接成的长方体，问哪一项可能是其正确的外表面展开图？","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"D","page":47,"stemImages":["banks/zhenti304_imgs/p048_f01.webp"]},{"id":167,"chapter":5,"num":7,"source":"2025国考副省级","type":"图形推理","stem":"左边为给定的多面体,现用经P、Q、R三个顶点的平面对其进行切割,问哪个选项是其切面？","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":48,"stemImages":["banks/zhenti304_imgs/p048_f02.webp"]},{"id":168,"chapter":5,"num":8,"source":"2025国考副省级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①②④，③⑤⑥","B":"①③⑤，②④⑥","C":"①③④，②⑤⑥","D":"①③⑥，②④⑤"},"answer":"C","page":48,"stemImages":["banks/zhenti304_imgs/p048_f03.webp"]},{"id":169,"chapter":5,"num":9,"source":"2025国考副省级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①②③，④⑤⑥","B":"①⑤⑥，②③④","C":"①②④，③⑤⑥","D":"①③⑤，②④⑥"},"answer":"C","page":48,"stemImages":["banks/zhenti304_imgs/p049_f01.webp"]},{"id":170,"chapter":5,"num":10,"source":"2025国考副省级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①②④，③⑤⑥","B":"①③④，②⑤⑥","C":"①②⑤，③④⑥","D":"①④⑤，②③⑥"},"answer":"B","page":49,"stemImages":["banks/zhenti304_imgs/p049_f02.webp"]},{"id":171,"chapter":5,"num":11,"source":"2025国考副省级","type":"定义判断","stem":"后视错觉是个体的一种认知偏差，是指在一件事情已经发生之后,即使个体之前没有对此做过预判,也认为自己“早就知道会这样”。","prompt":"根据上述定义,下列符合后视错觉的是：","options":{"A":"小瑾是一个悲观的人，她申请升职失败后，灰心丧气地说：“我早就知道，我什么都不如别人，什么也做不好。”","B":"朋友邀阿欣去爬山，阿欣说高温预警不宜爬山，朋友坚持去，才到半山腰就汗流渎背，阿欣说：“我早就说会很热啊。”","C":"晓琳参加一个重要会议迟到了。她懊悔地说：“我早该想到周一早上会堵车，不该按周末的情况预估通勤时间。”","D":"晓菲在股票大跌之后，懊恼地说：“我早就觉察到那些信号了，觉得走势不太好，怎么就没有早卖出啊。”"},"answer":"D","page":49},{"id":172,"chapter":5,"num":12,"source":"2025国考副省级","type":"定义判断","stem":"回应型预算要求政府基于与人民的民主协商作出预算决策，相关责任部门应当及时反应并积极回复人民的质疑和诉求。","prompt":"根据上述定义,下列属于回应型预算的是：","options":{"A":"甲国突发大规模严重旱情，财政部门从中央及各级政府应急预算中，通过多种财政政策安排,保障应急救援经费","B":"乙省是地质灾害高发地区，年初该省编制《乙省地质灾害应急中心 XX年度部门预算公开说明》并在官网上发布","C":"丙市在年初将上一年度的地方预算执行情况在官网进行公布，诚邀广大市民和社会公众踊跃监督并提出意见","D":"丁区实行预算听证制度，对与公共服务和社会民生相关的重大支出项目开展听证,并就意见和建议进行书面答复"},"answer":"D","page":50},{"id":173,"chapter":5,"num":13,"source":"2025国考副省级","type":"定义判断","stem":"选择或然率理论解释的是影响受众对大众传播内容选择的决定性因素。该理论的核心公式是：选择或然率=报偿的保证/费力的程度。其中，报偿的保证指的是传播内容满足选择者需要的程度,即内容对于受众的吸引力和实用性;费力的程度指的是获取传播内容和使用传播途径的难度。","prompt":"根据上述定义,下列属于提高选择或然率的传播行为的是:","options":{"A":"视频号平台借助数据分析和个性化算法,给用户推荐符合其偏好的视频","B":"时下流行的某影视作品在播放之前被插入一段2 分钟的广告","C":"某商家优化了商品布局，将畅销商品放在出口处，顾客可直接扫码支付","D":"电视内置视频播放软件,开机后须先注册登录，才可搜索相关内容观看"},"answer":"A","page":50},{"id":174,"chapter":5,"num":14,"source":"2025国考副省级","type":"定义判断","stem":"三维反求是测量技术、数据处理技术、图形处理技术和加工技术相结合的综合性技术,是指用一定的测量方法对实物进行测量，根据测量数据通过三维几何建模方法重构实物的数字化模型的过程。\n根据上述定义,下列关于三维反求工程的步骤，排序正确的是:\n①通过制造样品来验证模型是否满足精度和其他性能指标\n②通过一定的算法，从测量数据中提取零件的设计与加工特征\n③使用高精度的三维测量技术获取零件表面各点的空间坐标\n④使用计算机辅助设计软件将数据与特征重构为三维模型","prompt":"","options":{"A":"①③④②","B":"①④③②","C":"③①②④","D":"③②④①"},"answer":"D","page":50},{"id":175,"chapter":5,"num":15,"source":"2025国考副省级","type":"定义判断","stem":"形象史学是指把形与象作为主要材料，用以研究历史的一门学问。具体来说，是指把传世的包括出土（水）的具有研究价值的石刻、陶塑、壁画、雕砖、铜玉、织绣、漆器、木器、绘画等历史实物、文本图像以及文化史迹作为主要研究对象，并结合传统文献来综合考察历史的一种新的史学研究模式。","prompt":"根据上述定义，下列属于形象史学研究范畴的是:","options":{"A":"结合《晋书》等史书，通过对吉林集安长川1号墓礼佛图主佛形象及莲花纹的考察，研究三燕文化对高句丽佛教产生的影响","B":"通过对现存的汉画像石（汉代人雕刻在墓室、祠堂四壁的装饰石刻壁画）的实地考察，分析汉画像石的雕刻风格和雕刻技法","C":"根据史诗《伊利亚特》的记载，找到特洛伊城的遗址，并在其中发掘出王冠、银瓶、短剑等大量器物","D":"通过对二十世纪二三十年代齐白石、傅抱石等人具有代表性的国画作品进行研究，分析当时国画中所蕴含的思想意境"},"answer":"A","page":51},{"id":176,"chapter":5,"num":16,"source":"2025国考副省级","type":"定义判断","stem":"深度优先搜索是指从初始节点出发，按照一定的顺序扩展到下一个节点，然后从下一个节点出发继续扩展到新的节点，不断递归执行这个过程，直到某个节点不能再扩展到下一个节点，此时返回上一个节点重新寻找一个新的节点继续扩展，如此搜索下去，直到找到目标节点，或者搜索完所有节点为止。","prompt":"根据上述定义，如果以\"1\"为初始节点，“12\"为目标节点，下列搜索路径符合深度优先搜索的是：","options":{"A":"1→2→1→3→6→11→12","B":"1→4→8→4→1→3→6→12","C":"1→3→5→3→7→3→6→12","D":"1→3→5→10→5→3→1→3→6→12"},"answer":"B","page":51,"stemImages":["banks/zhenti304_imgs/p051_f01.webp"]},{"id":177,"chapter":5,"num":17,"source":"2025国考副省级","type":"定义判断","stem":"元科学也称元理论，是一种以科学为研究对象的学科，它研究科学的性质、特征、形成和发展规律。科学概念是“科学内部\"出现的概念，如“质量\"频率\"等;而元科学概念是“谈论科学的”,表示科学的陈述或活动特征的概念。","prompt":"根据上述定义,下列说法正确的是：","options":{"A":"“黑洞\"是科学概念，“量子\"是元科学概念","B":"\"物质波\"科学\"都是科学概念","C":"“理论\"确证\"都是元科学概念","D":"\"经验\"是科学概念，“宇宙\"是元科学概念"},"answer":"C","page":52},{"id":178,"chapter":5,"num":18,"source":"2025国考副省级","type":"定义判断","stem":"同一认定是指侦查中具有专门知识的人或了解客体特征的人，通过比较先后出现的客体的特征而对客体是否同一做出的判断。这里所说的客体是指与案件有关联的人或物。","prompt":"根据上述定义,下列属于同一认定的是：","options":{"A":"通过对手机中所存储的信息进行检查，确定其是否为报案人所丢失的手机","B":"通过对犯罪现场提取的 DNA 信息与 DNA 信息库进行比对，查找犯罪嫌疑人","C":"通过对走私案中所缴获的走私物品进行多次鉴定，认定其是否为国外某厂家所生产","D":"通过对犯罪嫌疑人车上所收缴的各类物品进行检验，判断其是否属于违禁物品"},"answer":"B","page":52},{"id":179,"chapter":5,"num":19,"source":"2025国考副省级","type":"定义判断","stem":"流域内降雨或融冰化雪都可以引起河水显著上涨。春季，气候转暖，流域内的季节性积雪融化、河流解冻或春雨，引起河水上涨称春汛。因正值桃花盛开时节，故亦称桃汛。我国北方，把春季河冰解冻引起的涨水现象专称为凌汛。夏季，流域内的暴雨或高山冰川和积雪融化，使河水急剧上涨，称夏汛。我国习惯上把发生在夏季三伏前后的汛水称为伏汛。秋季由于暴雨，河水发生急剧上涨称秋汛。","prompt":"根据上述定义,下列判断错误的是：","options":{"A":"春汛包含凌汛","B":"夏汛包含伏汛","C":"伏汛在凌汛前","D":"春汛就是桃汛"},"answer":"C","page":52},{"id":180,"chapter":5,"num":20,"source":"2025国考副省级","type":"定义判断","stem":"具有包含与被包含关系的三个概念，如植物、乔木、水杉等，可至少形成三个正确的命题：所有的水杉都是乔木，所有的乔木都是植物，所有的水杉都是植物，由“所有的乔木都是植物\"所有的水杉都是植物\"而得出“所有的水杉都是乔木”,这样的推理被称为排序推理。","prompt":"根据上述定义,下列属于排序推理的是：","options":{"A":"所有的平行四边形都是四边形，所有的菱形都是四边形，所以，所有的菱形都是平行四边形","B":"所有的昆虫都是动物，所有的蝴蝶都是昆虫，所以，所有的蝴蝶都是动物","C":"所有的文字都是符号，所有的文字都是图形，所以，所有的符号都是图形","D":"这个花园的花都是迎春花，迎春花都在冬、春季开放，所以，这个花园的花都在冬、春季开放"},"answer":"A","page":52},{"id":181,"chapter":5,"num":21,"source":"2025国考副省级","type":"类比推理","stem":"逐客令：挡箭牌","prompt":"","options":{"A":"急先锋：领航者","B":"避风港:马后炮","C":"敲门砖：绊脚石","D":"鸿门宴:攻心计"},"answer":"C","page":53},{"id":182,"chapter":5,"num":22,"source":"2025国考副省级","type":"类比推理","stem":"婴其鸣矣:求其友声","prompt":"","options":{"A":"遏其生气:以求重价","B":"求之其本:经旬必得","C":"道不拾遗：夜不闭户","D":"避其锐气:击其惰归"},"answer":"A","page":53},{"id":183,"chapter":5,"num":23,"source":"2025国考副省级","type":"类比推理","stem":"直观性：即时性:网络直播","prompt":"","options":{"A":"等边性：对称性:等腰梯形","B":"公开性：权威性:行政法律","C":"周期性:延展性：机械钟摆","D":"挥发性:保温性：石棉纤维"},"answer":"B","page":53},{"id":184,"chapter":5,"num":24,"source":"2025国考副省级","type":"类比推理","stem":"光伏电站：电池板：发电","prompt":"","options":{"A":"跨海大桥:桥墩支架:交通","B":"射电望远镜:电磁波：信号","C":"海底气田:油气管道：钻井","D":"游乐设施:球幕电影：娱乐"},"answer":"A","page":53},{"id":185,"chapter":5,"num":25,"source":"2025国考副省级","type":"类比推理","stem":"稀树草原 对于()相当于()对于 国际公约","prompt":"","options":{"A":"物种多样性;缔约国家","B":"落叶阔叶林;多边条约","C":"气候变迁;政治协调","D":"植被类型;联合国宪章"},"answer":"D","page":54},{"id":186,"chapter":5,"num":26,"source":"2025国考副省级","type":"逻辑判断","stem":"某企业对于如何进行产教融合，形成如下两种方案：一是“做深”，企业自建培训中心，成立专职和兼职的企业培训师队伍,并根据企业需求,制定专门的培训大纲和计划,该中心与毕业生未来形成签约。二是“做浅”，在学校设立“冠名班\"和“订单班”,以学校教育为主,企业与学生当前没有签约意向，但随时保持互相选择的权利。","prompt":"以下理由中,能够支持企业选择第二方案的是：","options":{"A":"企业必须付出人力成本，人力资源自带“稀缺\"和“增值\"属性，在企业面临竞争压力时尤其要重视","B":"企业订单量并不是稳定的，遇到订单量突然增加需要扩产的时候，才临时需要大量的人参与进来","C":"该企业生产使用的是特种专业设备,竞争对手稀少，不具备从市场上挖掘技术人员的条件","D":"学校教育内容具有普适性,而自建培训中心有利于企业保障准员工的培养质量,提前锁定毕业生"},"answer":"B","page":54},{"id":187,"chapter":5,"num":27,"source":"2025国考副省级","type":"逻辑判断","stem":"海山是海面下的岛屿，与岛屿中的火山岛有相同的起源和相似的形态，以往的海山生物调查发现,海山岩石上的生物群落与海山周边的软底沉积和深海平原上的生物群落大不相同。而且,一些海山之间的生物群落在物种构成上较少重叠。因此，有一些学者认为，相对孤立的海山存在独特的生物群落且拥有高度特有的动物群。","prompt":"以下哪项如果为真,最能反驳上述学者的观点？","options":{"A":"远离大陆的孤岛,因为海洋的分割往往会形成相对孤立且独特的岛屿生物群","B":"物理隔离海洋的现象在海洋中很少出现,所以海山不可能长期被隔离成水下孤岛","C":"早期一些海山中发现的高度特有物种其实是采样不足造成的，很多海山都有相同的生物来源","D":"地形和海流的相互作用在某些海山顶部形成封闭环流，使栖息其上的生物幼体难以扩散"},"answer":"C","page":54},{"id":188,"chapter":5,"num":28,"source":"2025国考副省级","type":"逻辑判断","stem":"飞行信息记录系统，也就是俗标的黑匣子，在空难事故调查中的重要作用不需赘言，但无论在陆上还是海上的空难事故中，搜寻黑匣子都极其不易。有人建议，可利用现在飞速发展的互联技术，把黑匣子升级成为“云匣子”，那么飞机在空中就能够实时与地面进行信息交互，使空难事故的分析变得更加便捷。","prompt":"以下哪项如果为真,最能质疑上述建议？","options":{"A":"飞机接入互联网，其信号稳定性受到太多外界不可控因素的影响","B":"空难是极小概率事件,投入高昂的数据管理成本不如直接用于提升飞行安全","C":"即使救援人员能够顺利搜寻到黑匣子，想要依靠其揭开事故真相也绝非易事","D":"实时同步每一架飞机的海量数据，对飞行管理并无帮助，更无必要"},"answer":"A","page":55},{"id":189,"chapter":5,"num":29,"source":"2025国考副省级","type":"逻辑判断","stem":"某项研究显示，与未接触空气污染的人相比，暴露于空气污染中的人死于乳腺癌的风险增加了80%,死于其他各类癌症的风险增加了22%。该研究团队由此认为，这可能与空气污染物中的 PM2.5有关,因为 PM2.5 会导致脏器的炎症和氧化应激反应。","prompt":"以下哪项如果为真，最可能是上述专家预设的前提？","options":{"A":"脏器的炎症和氧化应激反应是明确的致癌危险因素","B":"PM2.5 在大气成分中含量较少，但对空气质量有重要影响","C":"吸食香烟和电子烟等都可以将 PM2.5直接输送到肺部","D":"女性更易接触烹饪油烟,其中含有大量的 PM2.5"},"answer":"A","page":55},{"id":190,"chapter":5,"num":30,"source":"2025国考副省级","type":"逻辑判断","stem":"甲、乙、丙、丁4人按顺时针依次围坐在四方桌前，每人坐一面，4人中只有1人说真话。\n甲：坐在东面的人说谎;\nZ:坐在南面的人说谎;\n丙：我坐在西面或者北面;\n丁:我坐在北面。","prompt":"根据以上陈述,可以得出：","options":{"A":"甲坐在北面","B":"甲坐在东面","C":"乙坐在西面","D":"乙坐在南面"},"answer":"A","page":55},{"id":191,"chapter":5,"num":31,"source":"2025国考副省级","type":"逻辑判断","stem":"随着通货膨胀的蔓延，H国电子企业主要产品的原材料价格大幅上涨。该国最大的电子企业公报显示,今年该企业智能手机应用处理器价格较上年上涨30%，用于智能手机的相机模块价格上涨11%，用于电视和显示器的面板价格上涨9%。H国经济界认为，电子企业原材料价格居高不下，将严重削弱该国电子企业在国际市场上的竞争力。","prompt":"以下哪项如果为真,最能支持上述结论?","options":{"A":"近年来,无论是国际还是国内，硅化合物价格始终呈上涨趋势，这是导致H国电子企业主要产品原材料价格大幅上涨的原因","B":"在H国电子企业主要产品的原材料价格大幅上涨的同时，由于购买力下降等原因，电子产品的全球消费需求在缩减","C":"其他国家电子企业都在通过科技创新降低产品原材料价格上涨的影响，以求通过低价在竞争激烈的国际电子产品市场中脱颖而出","D":"一直以来，H国电子企业生产的产品以其卓越的技术和质量优势在国际市场上极具竞争力，近年来这种竞争优势在逐渐减弱"},"answer":"C","page":55},{"id":192,"chapter":5,"num":32,"source":"2025国考副省级","type":"逻辑判断","stem":"我军军语惯于将数字1、2、7、9、0变读为幺、两、拐、勾、洞,这些数字有个共同特点，即其原本的发音部位与发音方法使得在读这些数字时无法发出较大声音，在噪声干扰较为强烈的战场上,通信兵使用通讯设备进行情报交流时，话筒对这些数字的实际增音效果并不明显,可能会影响信息的准确性。因此，在军语中将这些数字变读，是为了符合实际需要。","prompt":"以下哪项如果为真,不能支持上述结论?","options":{"A":"常规数字念法中1、7的韵尾相同，发音相似，在嘈杂的战场环境中容易混淆，造成信息传达错误","B":"士兵一般都来自不同的兵源地，不可避免地带有家乡口音，将数字变读可以避免口音问题","C":"在国际无线电通话中，也会对字母读音进行变读，如将 A 读成 Alpha，将D 读成 Delta","D":"将0读成“洞\"时,更容易提高声音,同时也使声音更加干脆清晰，确保信息的准确性"},"answer":"C","page":56},{"id":193,"chapter":5,"num":33,"source":"2025国考副省级","type":"逻辑判断","stem":"国内市场只有形成完备的市场体系与商业规则环境，才能为企业参与出口竞争提供真正的市场根基,要形成完备的市场体系，必须深化要素市场化配置体制机制改革,只有促进要素自主有序流动,且提高要素配置效率，才能深化要素市场化配置体制机制改革,要形成完备的商业规则环境，必须推进全方位开放并建立全国统一大市场，且加强执法效率和市场司法保障。","prompt":"根据以上陈述,可以推出下列哪项？","options":{"A":"只要深化要素市场化配置体制机制改革就能形成完备的市场体系","B":"如果加强执法效率和司法保障，就能推进全方位开放并建立全国统一大市场","C":"只有促进要素自主有序流动，且提高要素配置效率，才能使国内市场形成完备的商业规则环境","D":"除非推进全方位开放并建立全国统一大市场，且加强执法效率和司法保障，否则不能为企业参与进出口竞争提供真正的市场根基"},"answer":"D","page":56},{"id":194,"chapter":5,"num":34,"source":"2025国考副省级","type":"逻辑判断","stem":"红霉素是一种抗生素，最早从放线菌糖多孢红霉菌的分泌物中发现，最新研究中，人们发现一种名为文蛤的贝类体内也会分泌红霉素。红霉素主要由微生物合成，此前从未在动物体内发现,研究者据此推测,文蛤合成红霉素的能力应当源于文蛤体内的微生物，正是这些微生物帮助文蛤合成了红霉素。","prompt":"以下哪项如果为真，最能削弱研究者的推测？","options":{"A":"文蛤的基因组中具有红霉素合成基因，该基因表达在文蛤外套膜的粘液细胞中","B":"文蛤贝壳下有一层外套膜，膜的上皮内分布着粘液细胞，它们能存储红霉素","C":"通过对文蛤体内的所有维生素进行检测并没有发现糖多孢红霉素菌","D":"研究者在其他贝类体内也发现了类似红霉素的抗生素"},"answer":"A","page":57},{"id":195,"chapter":5,"num":35,"source":"2025国考副省级","type":"逻辑判断","stem":"甲、乙、丙、丁、戊、己、庚7人报名参加象棋比赛，对于比赛结果，大家预测如下:\n（1）戊、己、庚至少有2人获奖;\n（2）如果甲、丙、戊至少有1人获奖，则丁、己均不获奖;\n（3）如果乙、戊、己至少有1人获奖，则丁获奖而丙不获奖。\n比赛结束后，发现上述预测完全正确。","prompt":"根据上述信息，一定获奖的是:","options":{"A":"甲","B":"乙","C":"丙","D":"丁"},"answer":"D","page":57},{"id":196,"chapter":6,"num":1,"source":"2026国考副省级","type":"图形推理","stem":"从所给的四个选项中,选择最合适的一个填入问号处,使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"A","page":58,"stemImages":["banks/zhenti304_imgs/p058_f01.webp"]},{"id":197,"chapter":6,"num":2,"source":"2026国考副省级","type":"图形推理","stem":"从所给四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"D","page":58,"stemImages":["banks/zhenti304_imgs/p058_f02.webp"]},{"id":198,"chapter":6,"num":3,"source":"2026国考副省级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"D","page":58,"stemImages":["banks/zhenti304_imgs/p058_f03.webp"]},{"id":199,"chapter":6,"num":4,"source":"2026国考副省级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"C","page":58,"stemImages":["banks/zhenti304_imgs/p059_f01.webp"]},{"id":200,"chapter":6,"num":5,"source":"2026国考副省级","type":"图形推理","stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":59,"stemImages":["banks/zhenti304_imgs/p059_f02.webp"]},{"id":201,"chapter":6,"num":6,"source":"2026国考副省级","type":"图形推理","stem":"左边为由 15个白色正方体和3个黑色正方体组合而成的多面体俯视图和左视图，其正视图可能是:\n俯视图左视图A B C D","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":59,"stemImages":["banks/zhenti304_imgs/p059_f03.webp"]},{"id":202,"chapter":6,"num":7,"source":"2026国考副省级","type":"图形推理","stem":"下图为由2个正方体组合而成的长方体，问这2个正方体的外表面展开图可能分别是：","prompt":"","options":{"A":"②和④","B":"②和③","C":"①和④","D":"①和③"},"answer":"D","page":59,"stemImages":["banks/zhenti304_imgs/p059_f04.webp","banks/zhenti304_imgs/p060_f01.webp"]},{"id":203,"chapter":6,"num":8,"source":"2026国考副省级","type":"图形推理","stem":"左边为由12个白色正方体和3个灰色正方体组合而成的多面体前后两面直观图，问其可以由除哪项外的三个多面体组合而成？","prompt":"","options":{"A":"","B":"","C":"","D":""},"answer":"B","page":60,"stemImages":["banks/zhenti304_imgs/p060_f02.webp"]},{"id":204,"chapter":6,"num":9,"source":"2026国考副省级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①②⑥，③④⑤","B":"①②④，③⑤⑥","C":"①⑤⑥，②③④","D":"①④⑥，②③⑤"},"answer":"B","page":60,"stemImages":["banks/zhenti304_imgs/p060_f03.webp"]},{"id":205,"chapter":6,"num":10,"source":"2026国考副省级","type":"图形推理","stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","prompt":"","options":{"A":"①②③，④⑤⑥","B":"①③④，②⑤⑥","C":"①③⑥，②④⑤","D":"①⑤⑥，②③④"},"answer":"C","page":60,"stemImages":["banks/zhenti304_imgs/p061_f01.webp"]},{"id":206,"chapter":6,"num":11,"source":"2026国考副省级","type":"定义判断","stem":"均变论认为，支配各种地质过程的法则在地质历史上没有发生过变化，现在起作用的各种自然营力在漫长的地质过程中具有普遍的均一性，即地质演变是一个渐变的过程,具有相同方式和相同的强度；地球上生物的种与种之间有过渡关系，生物进化过程是极其漫长的。灾变论认为，在整个地质发展的过程中，地球经常发生各种突如其来的、短暂的全球性灾难性变化，这些变化强烈地改变了地球的面貌;地球上生物的变化是反复多次灾变的结果。","prompt":"根据上述定义,下列说法最能体现灾变论观点的是：","options":{"A":"“我们找不到开始的痕迹，也看不到结束的迹象”","B":"“地质记录是一部被鲜血和火焰写成的史诗”","C":"“现在是通往过去的一把钥匙”","D":"“自然界里没有飞跃”"},"answer":"B","page":61},{"id":207,"chapter":6,"num":12,"source":"2026国考副省级","type":"定义判断","stem":"波特五力模型是一种竞争分析工具，用于评估一个行业的竞争力和吸引力。该模型通过对同行业竞争对手的威胁、潜在进入者的威胁、替代品的威胁、上游供应商的议价能力和下游购买者的议价能力这五个方面的分析，帮助企业了解其所处行业的竞争环境，以制定相应的竞争策略。","prompt":"根据上述定义,关于康复机器人行业,对下列问题的分析不能归入波特五力模型的是：","options":{"A":"康复机器人行业准入门槛高吗？需要强大的技术能力和创新能力吗？","B":"医院和康复中心患者规模如何？对于康复机器人的需求有多大？","C":"与传统物理治疗等康复治疗方法相比，康复机器人有竞争力吗？","D":"康复机器人企业内部各部门之间的协同合作程度高吗？"},"answer":"D","page":61},{"id":208,"chapter":6,"num":13,"source":"2026国考副省级","type":"定义判断","stem":"选矿是指用物理、化学或者物理与化学相结合的方法，将原矿中的有用矿物与伴生的无用固定物质（脉石）或有害矿物分开的过程。选矿可显著提高矿石的质量，减少运输费用，降低冶炼成本，进而实现综合利用。","prompt":"根据上述定义，下列没有体现选矿过程的是：","options":{"A":"利用矿物颗粒电性的差别，在高压电场中挑选出白钨矿、赤铁矿等,通过电机分离除尘","B":"利用水枪和洗矿槽等设备，将锡矿石中的泥土等杂质洗去，同时也可以将部分轻矿物冲走，实现锡石初步富集","C":"经验丰富的老师傅通过敲击、光照、观察皮壳等方法对开采的翡翠原石进行筛选，挑选优质原石","D":"将铜矿矿石破碎到一定的粒度后，混以少量的食盐和煤粉隔氧加热，矿石中的铜便以金属状态析出,由此获得铜精矿"},"answer":"C","page":62},{"id":209,"chapter":6,"num":14,"source":"2026国考副省级","type":"定义判断","stem":"根据动词对其后所接的宾语小句（作宾语的句子）真值的不同预设能力可以把现代汉语中的相关动词分为叙实动词、非叙实动词和反叙实动词。叙实动词的肯定式和否定式都预设其宾语小句为真;非叙实动词的肯定式和否定式都不预设其宾语小句为真,也不预设其宾语小句为假;反叙实动词的肯定式和否定式都预设其宾语小句为假。根据上述定义,下列画线的动词属于非叙实动词的是：","prompt":"","options":{"A":"我听说他来过这里","B":"我庆幸听了你的建议","C":"我知道你帮助过我","D":"我幻想成为一只小鸟"},"answer":"A","page":62},{"id":210,"chapter":6,"num":15,"source":"2026国考副省级","type":"定义判断","stem":"动作预期是指运动员在比赛过程中，根据已有信息，对即将发生的动作结果进行预测的过程。在这一过程中，运动员主要依赖两类信息：运动学信息和情境先验信息。运动学信息包括对手的动作、器材的运动轨迹或队员之间的相对位置，情境先验信息则涉及比赛情境中事件发生的概率。","prompt":"根据上述定义,下列不涉及上述任何一种信息的是：","options":{"A":"篮球队员甲在双方比分紧咬的情况下，基于对手今日比赛罚篮命中率不高，在对手投篮时选择直接犯规","B":"网球运动员乙知道对手在比赛前有一系列习惯性动作，包括整理球衣、球裤、头发等，暗自提醒自己不要被其干扰","C":"羽毛球双打运动员丙发现对方准备接发球的球员位置稍微靠前，可能来不及转身或后退接球，便发了个后场球","D":"乒乓球运动员丁发现对方发过来的球位置较低、速度较慢，极有可能擦网变线，便没有后退，向前伸拍做好接球准备"},"answer":"B","page":62},{"id":211,"chapter":6,"num":16,"source":"2026国考副省级","type":"定义判断","stem":"设备利用率是指每年度设备实际使用时间占计划用时的百分比。设备完好率是根据各类设备完好标准，对企业设备进行逐台检查所确定的完好台数与设备总台数之比。设备总台数是指企业在用的、备用的、停用的以及正在检修的全部生产设备台数，完好台数是指设备性能良好、运转正常，且原料、燃料、油料等消耗正常的设备台数。设备负荷率是指设备需要台数与实际选用设备的台数之比。设备闲置率是指闲置不用的设备台数与设备总台数的比值。","prompt":"根据上述定义，下列说法错误的是：","options":{"A":"若年度设备实际使用时间为9个月、设备利用率为75%，则计划用时为12个月","B":"企业正在检修的、零部件出现磨损或腐蚀的设备应当纳入设备总台数的计算中","C":"设备负荷率可用来考核设备选用的合理性程度，可用于量化分析设备运行状态","D":"设备闲置率可以反映出设备资产投资的回报程度，其数值一般小于设备完好率"},"answer":"D","page":63},{"id":212,"chapter":6,"num":17,"source":"2026国考副省级","type":"定义判断","stem":"分项累进淘汰法是指在对植株进行选种时，根据性状的相对重要性顺序排列，先按第一重要性状进行选择，然后在入选株内按第二重要性状进行选择，依此顺次累进的一种选种方法。","prompt":"根据上述定义,下列对南瓜的选种方法属于分项累进淘汰法的是：","options":{"A":"按株选目标性状出现的先后顺序，先淘汰蔓生植株，然后淘汰第一雌花节位高的植株，再淘汰单瓜重量低的植株","B":"首先在群体内选择无病植株，再在这些无病植株内选择丰产性好的植株,再根据产量性状顺次进行选择","C":"在收获时按照果实的大小、果型等性状初选，在初选瓜内再按照综合性状入选标准进行复选","D":"将需要鉴定的性状，如蔓长、单瓜重、果实籽粒数、籽粒长等，分别规定一个最低的入选标准，将低于入选标准的淘汰"},"answer":"B","page":63},{"id":213,"chapter":6,"num":18,"source":"2026国考副省级","type":"定义判断","stem":"组织结构可以划分为以下几种类型：（1）直线型组织结构，即每一个部门只对其直接的下属部门下达工作指令，不能越级指挥，每一个部门也只有一个直接的上级部门;(2)职能型组织结构,即每一个部门都可对其下属部门下达工作指令，每一个下属部门可能得到不同上级部门下达的多个工作指令；（3）直线职能型组织结构，即在主管之下设置相应的职能部门,实行主管统一指挥与职能部门参谋指导相结合的管理方式,各部门既受上级的管理，又受同级职能管理部门的业务指导和监督;（4）事业部组织结构，即由相对独立的事业部组成的组织结构，通常按照地区或项目来划分事业部,每个事业部拥有较大的自主权。","prompt":"根据上述定义,下列组织结构图代表的组织结构类型属于：","options":{"A":"直线型组织结构","B":"职能型组织结构","C":"直线职能型组织结构","D":"事业部组织结构"},"answer":"B","page":64,"stemImages":["banks/zhenti304_imgs/p064_f01.webp"]},{"id":214,"chapter":6,"num":19,"source":"2026国考副省级","type":"定义判断","stem":"《中国共产党纪律处分条例》规定，主动交代本人应当受到党纪处分的问题，可以从轻或者减轻处分。这里所称的主动交代主要包括两种情况：一是涉嫌违纪的党员在组织谈话函询、初步核实前向有关组织交代自己的问题。二是在谈话函询、初步核实和立案审查期间交代组织未掌握的问题。","prompt":"假定下列入员均受该条例约束，根据上述定义,下列属于主动交代的是：","options":{"A":"甲在参加违纪违法典型案例警示教育大会后,主动找到单位领导反映同事的违纪问题","B":"乙在组织对其进行廉政谈话时，组织举证一项他才承认一项，对未涉及的情况闭口不谈","C":"丙在纪委对其个人财产有关事项进行函询时，将其利用职权为自己和他人谋利的情况如实交代","D":"丁在纪委对其立案审查期间，面对确凿的证据，交代了之前没有交代的收受大额礼金的问题"},"answer":"C","page":64},{"id":215,"chapter":6,"num":20,"source":"2026国考副省级","type":"定义判断","stem":"心理护理是指在护理过程中，护士发现了影响患者治疗及康复的心理问题后，运用心理学的理论作指导，通过自身的语言、态度和行为等，或通过改善环境（包括人文环境及物理环境）去影响或调整患者的心理状态和行为，进而帮助患者康复的护理方法。","prompt":"根据上述定义，下列没有体现心理护理的是:","options":{"A":"护士协助医生让青少年患者进行心理量表的测试,进而评估患者心理问题的类型","B":"护士发现患儿害怕用药后，在更换伤口敷料时动作轻柔、耐心细致，使患儿不再抵触换药","C":"护士建议家属及时安抚患者的消极情绪并多加陪伴,以增强患者战胜疾病的信心","D":"针对患者手术前的紧张情绪，护士教会患者放松的技巧，帮助患者正确对待手术"},"answer":"A","page":64},{"id":216,"chapter":6,"num":21,"source":"2026国考副省级","type":"类比推理","stem":"与“军事演习：作战能力\"在逻辑关系上最相近的是：","prompt":"","options":{"A":"正当防卫：人身危险","B":"定速巡航：车辆速度","C":"财政赤字：通货膨胀","D":"土壤改良：作物产量"},"answer":"D","page":65},{"id":217,"chapter":6,"num":22,"source":"2026国考副省级","type":"类比推理","stem":"与“口腔：唾液：淀粉酶\"在逻辑关系上最相近的是：","prompt":"","options":{"A":"种子:孜然：调味品","B":"叶片：叶肉：叶绿体","C":"松树：松脂：树脂醇","D":"试剂:试纸：pH试纸"},"answer":"C","page":65},{"id":218,"chapter":6,"num":23,"source":"2026国考副省级","type":"类比推理","stem":"与\"减数：被减数：差\"在逻辑关系上最相近的是：","prompt":"","options":{"A":"粮食产量:播种面积:粮食单产","B":"溶质质量:溶液质量：溶剂质量","C":"可售天数:库存总量：日均销量","D":"间隔天数:结束日期：开始日期"},"answer":"B","page":65},{"id":219,"chapter":6,"num":24,"source":"2026国考副省级","type":"类比推理","stem":"颅内疾病 对于()相当于（）对于 岩石断裂依次填入括号中最恰当的是:","prompt":"","options":{"A":"颅内感染;岩石熔融","B":"机体疾病;地壳应力","C":"核磁共振;地下采样","D":"视野缺失;冰川运动"},"answer":"D","page":65},{"id":220,"chapter":6,"num":25,"source":"2026国考副省级","type":"类比推理","stem":"如果用一个圆来表示词语所指称的对象的集合，那么以下哪项中画横线词语之间的关系符合下图?","prompt":"","options":{"A":"船舶按用途分为军用船舶（①）和民用船舶两大类，潜艇、航空母舰（③）、驱逐舰等都属于军用船舶;按推进动力分为机动船和非机动船（②）","B":"水杉（③）是我国的特有树种，属于落叶树（①），是一种高大的乔木（②），是世界上珍稀的“活化石\"植物","C":"图书按照读者群可分为少儿读物（③）和成人读物等；按照载体可分为纸质书和电子书（②）等;按照学科可分为历史书、文学书和哲学书（①）等","D":"大熊猫属于哺乳动物（①），是中国特有动物（②），被列为中国国家一级保护野生动物（③）"},"answer":"B","page":65,"stemImages":["banks/zhenti304_imgs/p065_f01.webp"]},{"id":221,"chapter":6,"num":26,"source":"2026国考副省级","type":"逻辑判断","stem":"研究发现，受人喜爱、知名度高的物种更易成为科研人员研究的对象。有观点认为，每一物种都有研究的意义和价值，科研人员不应对研究对象差别对待，但反对者却认为，科学研究进行重点突破比一视同仁\"更有意义，因为把有限的科研资源用在合适的地方，才能更好地平衡投入与回报。","prompt":"以下哪项如果为真,没有支持反对者的观点？","options":{"A":"关系人类基本需求的粮食作物，家禽家畜等产能的不断增长，得益于当初人们对其进行选择性的专门研究","B":"对那些生长周期短、基因组简单且分布广泛的模式生物进行重点研究更易揭示生命科学的普通规律","C":"由于文化、知名度等原因，对某些物种的保护性研究对唤醒人们的生态保护意识具有特殊的号召力和吸引力","D":"网络上搜索到关于树袋熊的相关论文有5000多篇，而更为濒危的昆士兰毛吻袋熊的论文则不到1000篇"},"answer":"D","page":66},{"id":222,"chapter":6,"num":27,"source":"2026国考副省级","type":"逻辑判断","stem":"部分研究认为，白垩纪陆地生态系统的变革是由植物、昆虫、脊椎动物与地质过程等多个要素相互作用推动的，形成了一个高度协同演化的系统结构。鉴于这一机制在当时造就了复杂而稳定的生态格局，有学者提出，现代陆地生态系统的高度复杂性，正是这种古老协同机制延续和演化的结果。","prompt":"以下哪项如果为真,最能削弱上述学者的观点？","options":{"A":"在地质记录中,白垩纪末期的生态危机主要影响海洋系统，而陆地系统显示出相对稳定的演替趋势","B":"对白垩纪地层的系统分析表明，植物、昆虫、脊椎动物与地质过程的演化几乎是在同一时期进行的","C":"现代陆地生态系统的复杂性主要受群落内部随机扰动、自组织演化和外源干扰的共同影响，与白垩纪显著不同","D":"被子植物的全球扩张早于部分动物类群多样化,其当时对生态结构的主导作用可能被高估"},"answer":"C","page":66},{"id":223,"chapter":6,"num":28,"source":"2026国考副省级","type":"逻辑判断","stem":"近年来,盲盒等“非确定性产品\"的市场规模迅速扩张，有分析人士指出，非确定性产品的热销说明有相当一部分消费者受到感受性消费动机的驱动，不同于实用性消费动机对商品实用价值的看重，感受性消费动机更看重商品带来的主观体验。以下哪项如果为真,不能支持上述分析人士的观点？","prompt":"","options":{"A":"盲盒等产品通常设计精美，能够给消费者带来愉悦的审美体验","B":"限量款盲盒产品吸引许多消费者以投资为目的购买并加价转手","C":"许多盲盒产品设计有隐藏款，消费者开出时会感受到惊喜、满足","D":"非确定性产品制造的信息缺口能够激发部分消费者强烈的好奇心"},"answer":"B","page":67},{"id":224,"chapter":6,"num":29,"source":"2026国考副省级","type":"逻辑判断","stem":"在过去几十年,某大型沿海河口的河岸和沼泽边缘不断被侵蚀且侵蚀速度逐渐加快，这使得河口的湿地退化，生态环境变得脆弱。同时，人们发现该河口中沼泽蟹的数量持续增加，这加剧了沼泽边缘的退缩。因此，可以适度引入海獭来减缓沼泽边缘的侵蚀。","prompt":"以下除哪项外，均能支持上述论证？","options":{"A":"沼泽蟹会在泥沙中挖掘洞穴，这是导致沼泽边缘不断退缩的主要原因","B":"该地区原有的海獭曾因人类活动而消失，重新引入不易引发生态失衡","C":"近年来,受海平面上升和潮汐冲刷的影响，许多河口都出现了湿地退化","D":"海獭是沼泽蟹的天敌，包括沼泽蟹在内的无脊椎动物是海獭的主要食物"},"answer":"C","page":67},{"id":225,"chapter":6,"num":30,"source":"2026国考副省级","type":"逻辑判断","stem":"某学术会议共有甲、乙、丙、丁、戊、己、庚7名代表参加，在专题讨论环节，受时间限制，对于代表发言的安排，有如下考虑：\n（1）甲、丁至多安排其中一人发言；\n（2）如果丙、戊至少安排其一，则安排甲而不安排已发言;\n（3）如果乙、庚至少安排其一，则安排丁而不安排甲发言。","prompt":"专题讨论最终安排了4名代表发言，上述考虑均被满足。下列说法正确的是：","options":{"A":"安排了乙、庚发言","B":"安排了丙、丁发言","C":"安排了己、戊发言","D":"安排了甲、乙发言"},"answer":"A","page":67},{"id":226,"chapter":6,"num":31,"source":"2026国考副省级","type":"逻辑判断","stem":"“三医”是医疗、医保、医药的简称，只有提高卫生事业发展水平，且相关部门密切合作、同向发力，才能促进“三医\"协同发展和治理。只有深化医改领导体制和工作推进机制，才能促进“三医\"协同发展和治理。深化医改领导体制和工作推进机制,必须强化区域医疗卫生规划和医疗机构设置规划的刚性约束。只有深化医改领导体制和工作推进机制，才能更好满足人民群众对美好生活的新期待，进而提高人民群众的获得感、幸福感和安全感。","prompt":"由此可以推出:","options":{"A":"只要提高卫生事业发展水平，就能使相关部门密切合作、同向发力","B":"只有强化区域医疗卫生规划和医疗机构设置规划的刚性约束，才能提高人民群众的获得感、幸福感和安全感","C":"要深化医改领导体制和工作推进机制,就必须促进“三医\"协同发展和治理","D":"如果不能更好满足人民群众对美好生活的新期待，就不能促进“三医\"协同发展和治理"},"answer":"B","page":67},{"id":227,"chapter":6,"num":32,"source":"2026国考副省级","type":"逻辑判断","stem":"抓挠是对皮肤瘙痒感觉的一种反应。一般来说，抓挠会激活皮肤中表达TRPV1的痛觉神经元，促进其释放P物质，激活肥大细胞，增强炎症反应，而最近的研究发现，皮肤瘙痒的小鼠抓挠皮肤后，相比未抓挠的皮肤，抓挠处的皮肤更少受到细菌感染。因此研究人员认为，抓挠皮肤并非毫无益处，这一行为可以增强该部位皮肤对细菌的防御能力。","prompt":"以下哪项如果为真,最能支持上述研究人员的观点？","options":{"A":"抓挠激活肥大细胞后，肥大细胞可在局部召集免疫细胞，进而抵抗病原菌的侵害","B":"近期一项研究发现，抓挠仅增加了皮肤的损伤程度，而并未加剧皮肤的炎症反应","C":"抓挠产生的痛感强度低于大脑疼痛阈值时，大脑会分泌血清素，让人产生愉悦感","D":"抓挠耳廓或耳垂能够刺激外耳皮肤中的迷走神经小分支,有助于增强神经活跃度"},"answer":"A","page":68},{"id":228,"chapter":6,"num":33,"source":"2026国考副省级","type":"逻辑判断","stem":"数据显示，当前我国的宠物数量已超过1.2亿只，养宠家庭规模破亿。在整体上升的趋势中，猫狗的数量增长并不同步，宠物猫的增速远高于宠物狗，尤其是在大城市，宠物猫的数量上升得更快。部分人士认为，随着城市化进程的加快，城市居民的居住空间越来越有限，养狗可能会面临空间不足的问题，而猫体型小巧，对空间的要求不高。因此居住空间受限是城市中的人们更倾向于养宠物猫的主要原因。","prompt":"以下除哪项外,均能削弱上述观点？","options":{"A":"狗易吠叫且更具人身危险性，容易引发邻里矛盾，有些居民担心养狗会带来麻烦","B":"猫不需每天遛,也不需花费大量时间陪伴，这对于上班族来说更具吸引力","C":"人们饲养宠物猫后，增加了与其他猫主人之间的交流，拓展了社交圈","D":"相比宠物狗，猫体型较小且食量也较少，食物和日常用品的开支较低"},"answer":"C","page":68},{"id":229,"chapter":6,"num":34,"source":"2026国考副省级","type":"逻辑判断","stem":"一项针对中学生的研究发现：直接使用通用AI工具可短暂提高学生数学测试成绩，但最终削弱了学生的数学学习能力。研究持续一学期，学生被分为三组，分别在课堂练习阶段使用不同工具：①组使用标准课本和笔记；②组使用通用AI工具，可以直接查询答案；C组使用特别设计的AI工具，指导而不直接给出答案。随堂考核发现，②组和C组学生比①组学生的成绩高出48%和127%。但期末考试时，②组比①组成绩低了17%;而C组和①组无明显差异。","prompt":"以下除哪项外，均能削弱上述结论？","options":{"A":"研究中未对学生做AI工具使用培训，研究结果不能说明正确使用AI工具的效果","B":"学生的数学基础水平、学习动机、课后自主练习等变量都会影响考试成绩","C":"研究仅针对数学学科，不能说明AI工具辅助教学对其他学科的影响","D":"研究持续时间不够，不足以说明长期使用AI工具可能带来的效果"},"answer":"C","page":68},{"id":230,"chapter":6,"num":35,"source":"2026国考副省级","type":"逻辑判断","stem":"R市最近出现较强降雨。因为冷空气与暖湿气流交汇时会产生强降雨，可见R市最近出现了冷空气与暖湿气流的交汇。","prompt":"以下哪项与上述论证方式最为相似？","options":{"A":"某草场今年牧草稀疏,因为牧草稀疏时绵羊无法摄入足够的营养，进而影响生长发育，所以该草场今年绵羊的生长发育会受到影响","B":"某地图书馆春节期间图书借阅量减少，因为旅游人数增加不会导致图书借阅量减少，可见该地图书馆图书借阅量减少与旅游人数增加无关","C":"由于地质松软会导致建设隧道时工期延长，某区域建设隧道时工期延长，所以该区域的地质松软","D":"因为小质量恒星坍缩后大多会变成白矮星，科学家发现某个小质量恒星正在发生坍缩，所以这个小质量恒星会变成白矮星"},"answer":"C","page":69}]});
